'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["ro"]={"g-flurpruefung":["Ce este inclus într-o inspecție vizuală și funcțională înainte de începerea lucrului?","Înainte de prima misiune a zilei.","Verificați doar nivelul combustibilului și culoarea vehiculului.","Verificați frânele, direcția, furcile, anvelopele și dispozitivele de siguranță conform instrucțiunilor de utilizare.","Efectuați un test de conducere cu sarcina ridicată.","Inspecția zilnică include părțile și funcțiile relevante pentru siguranță conform instrucțiunilor de utilizare."],"g-rueckhalt":["Cum te descurci cu sistemul de reținere al șoferului existent?","Stivuitorul are un sistem de reținere obligatoriu.","Folosiți-l corect în timp ce conduceți.","Utilizați numai pe podele neuniforme.","Dezactivați-l pentru călătorii scurte.","Sistemele de reținere prevăzute trebuie utilizate în conformitate cu instrucțiunile producătorului; ele oferă o protecție specială în cazul unor evenimente de basculare."],"g-mangelmelden":["Ce se aplică unui stivuitor cu furca deteriorată?","La verificare, observați un cuțit clar îndoit.","Dacă este posibil, distribuiți sarcina pe celălalt dinți.","Conduceți doar încărcături ușoare până la următorul service.","Nu folosiți stivuitorul și raportați defecțiunea persoanei responsabile.","Echipamentele de manipulare a încărcăturii deteriorate se pot defecta; Defectele legate de siguranță necesită oprire până la clarificare."],"g-einweisung":["Treci la un stivuitor cu diferite comenzi. Ce este necesar înainte de utilizare?","Funcționarea diferă de vehiculul dumneavoastră anterior.","Instrucțiuni legate de dispozitiv și respectarea instrucțiunilor de utilizare.","O scurtă explicație de la un coleg neimplicat este întotdeauna suficientă.","Nu există informații suplimentare dacă aveți permis de stivuitor.","O calificare generală nu înlocuiește instrucțiunile necesare privind dispozitivul utilizat efectiv."],"g-anbaugeraet":["Ar trebui să utilizați un atașament. Ce verifici mai intai?","Un nou echipament modifică modul în care este preluată încărcătura.","Dacă atașamentul se potrivește cu aprobarea vehiculului și cu sarcina admisă.","Doar dacă dispozitivul poate fi atașat vizual.","Dacă atașamentul poate fi instalat fără documente.","Atașamentele pot modifica capacitatea de încărcare rămasă și centrul de încărcare; Aprobarile și informațiile despre capacitatea de încărcare trebuie verificate."],"g-diagramm":["De ce aveți nevoie de diagrama capacității de încărcare?","Este prezentă o sarcină grea cu centrul de greutate mult în exterior.","Pentru a determina traseul cel mai scurt.","Pentru a evalua sarcina maximă admisă în funcție de înălțimea de ridicare și centrul de încărcare.","Pentru a determina capacitatea rezervorului.","Sarcinile permise depind, printre altele, de distanța centrului de sarcină și de înălțimea de ridicare."],"g-lastschwerpunkt":["Ce se întâmplă de obicei când centrul de greutate se deplasează mai departe?","O sarcină lungă iese mult în fața furcilor.","Capacitatea de sarcină admisă poate scădea.","Capacitatea de transport este mereu în creștere.","Distanța nu are nicio influență asupra momentului de răsturnare.","O distanță mai mare față de centrul de încărcare crește momentul de basculare și poate reduce capacitatea de încărcare admisă."],"g-gabelabstand":["Cum ar trebui să ridice furcile un palet potrivit?","Doriți să ridicați un palet încărcat uniform.","Cu dinții cât mai aproape și doar pe un colț.","Cu o distanță atât de mare încât paletul se răsturnează în lateral.","Cu o distanță adecvată a dintre dinți și o suprafață de sprijin și tren de rulare suficientă.","Sarcina trebuie susținută în siguranță și cât mai uniform posibil peste furci."],"g-schieflast":["O încărcătură este stivuită instabil. Ce este corect?","Cutiile de carton pot cădea atunci când sunt ridicate.","Începeți încet; sarcina se stabilizează singură.","Înainte de a ridica încărcătura, asigurați-o suficient sau reasamblați-o.","Ridicați sarcina deasupra înălțimii capului, astfel încât să nu stea în cale.","Încărcătura liberă sau instabilă poate cădea și poate pune în pericol oamenii; luați mai întâi măsurile de siguranță."],"g-personen":["Poate fi ridicată o persoană pe furci obișnuite?","Un coleg vrea să ajungă la o lumină.","Da, dacă colegul poartă cască.","Nu, numai instalațiile desemnate și permise pot fi folosite de oameni în conformitate cu cerințe speciale.","Da, dacă se apropie doar de o înălțime mică.","Furcile normale nu sunt o platformă de lucru personală; Transportul și ridicarea persoanelor sunt supuse unor cerințe speciale."],"g-transporthoehe":["Cum transportați de obicei un palet?","Drumul este clar și plan.","Cu sarcina ridicată numai în măsura în care este necesar și în conformitate cu instrucțiunile de utilizare.","Cu sarcina ridicată cât mai sus pentru a fi văzută mai bine.","Cu catargul de ridicare înclinat puternic înainte, indiferent de sarcină.","O pozitie joasa de transport reduce riscul de rasturnare si coliziuni; Instrucțiunile dispozitivului sunt decisive."],"g-kurvenfahrt":["De ce este periculos să virați rapid cu un stivuitor?","Vrei să ieși rapid pe o potecă îngustă.","Pentru că pur și simplu consumă bateria mai repede.","Pentru că stivuitorul se orientează automat mai bine.","Deoarece forțele laterale afectează stabilitatea și pot duce la răsturnarea.","La viraj, intră în joc forțe suplimentare; viteza trebuie ajustată la sarcină și condiții."],"g-ladebruecke":["Ce verificați înainte de a merge pe un pod de încărcare?","Ar trebui să conduci într-un camion.","Doar dacă poteca pare suficient de largă.","Capacitate de încărcare, suport sigur și protecție împotriva deplasării, precum și asigurarea vehiculului.","Doar dacă iluminarea este aprinsă.","Podurile de încărcare și vehiculele trebuie să fie asigurate împotriva mișcării și adecvate încărcăturii."],"g-fussgaenger":["Cum te comporți la o intersecție confuză cu pietonii?","Conexiunile vizuale sunt restricționate.","Conduceți cu o viteză adecvată, opriți-vă dacă este necesar și asigurați vizibilitate sigură.","Solicitați întotdeauna dreptul de trecere atunci când transportați o încărcătură.","Doar claxonați și continuați să conduceți.","Pietonii au nevoi speciale de protectie; Viteza, vizibilitatea și comunicarea trebuie adaptate rutei de circulație."],"g-batterieladen":["La ce ar trebui să acordați o atenție deosebită atunci când încărcați o baterie de unitate?","Se folosește o stație de încărcare a bateriei.","Locul de încărcare poate fi selectat indiferent de instrucțiunile producătorului.","Flăcările deschise sunt permise atâta timp cât camionul este staționat.","Zona de încărcare adecvată, ventilație suficientă și specificațiile producătorului, precum și protecție împotriva incendiilor și exploziilor.","La încărcare, pot apărea pericole din cauza energiei electrice, a gazelor și a substanțelor chimice; trebuie respectate masurile de protectie prevazute."],"h-beauftragt":["În ce condiții aveți voie să operați independent o platformă de lucru aeriană?","Ar trebui să utilizați o platformă de lucru în companie.","Dacă ai permis de conducere auto.","Dacă sunteți potrivit, instruit sau calificat și comandat de către angajator.","Dacă ați văzut vreodată o platformă de lucru.","Angajatorul trebuie să asigure adecvarea, calificările și misiunile în conformitate cu cerințele operaționale."],"h-vorpruefung":["Ce trebuie verificat înainte de a începe lucrul cu platforma de lucru aeriană?","Scena era afară peste noapte.","Test vizual și funcțional conform instrucțiunilor producătorului, inclusiv dispozitivele de siguranță.","Doar culoarea și vârsta scenei.","Dacă materialul de lucru este deja pe platformă.","Înainte de utilizare, mașina, comenzile, funcțiile de urgență și deteriorarea vizibilă trebuie verificate în conformitate cu instrucțiunile de utilizare."],"h-tragfaehigkeit":["Ce informații determină sarcina admisă pe coșul de lucru?","Două persoane ar dori să ia instrumente suplimentare cu ei.","Oamenii sunt liberi să estimeze greutatea totală admisă.","Doar greutatea celui mai greu contează.","Specificațiile privind capacitatea de încărcare pentru oameni, unelte și materiale nu trebuie depășite.","Sarcina nominală se referă la sarcina totală admisă, inclusiv orice material transportat."],"h-untergrund":["Ce ai în vedere înainte de a amenaja o scenă cu suporturi?","Lucrezi în apropierea unei zone pline.","Numai la îndemâna boom-ului.","Verificați capacitatea portantă și uniformitatea subsolului, precum și suportul adecvat conform instrucțiunilor.","Pe cel mai mic număr posibil de suporturi extinse.","Pamantul insuficient sau sprijinul necorespunzator poate duce la pierderea stabilitatii."],"h-wind":["Apare vântul puternic. Cum procedați?","Te trezești cu o scenă în aer liber.","Respectați limitele producătorului și dacă acestea sunt depășite, opriți funcționarea sau coborâți coșul în siguranță.","Extindeți platforma cât mai mult posibil, astfel încât să fie mai stabilă.","Reacționați numai dacă obiectele libere cad.","Condițiile de vânt permise de producător sunt limite de funcționare; Vântul poate crea forțe suplimentare periculoase."],"h-strom":["Trebuie să lucrați în apropierea unei linii electrice aeriene. Ce este crucial?","O linie activă este în zona de lucru.","O cască înlocuiește menținerea unei distanțe de siguranță.","Doar izolați coșul și lucrați fără coordonare.","Clarificați zona periculoasă și asigurați distanțele de protecție necesare sau alte măsuri adecvate.","Erupția electrică este posibilă și fără contact direct; Măsurile de protecție necesare trebuie stabilite înainte de începerea operațiunii."],"h-notablass":["De ce trebuie cunoscută procedura de coborâre de urgență?","Este posibilă o defecțiune a controlului normal.","Astfel încât în ​​cazul unei defecțiuni, salvarea în siguranță este posibilă în funcție de dispozitiv.","Pentru ca dispozitivul să funcționeze mai repede în funcționare normală.","Pentru a înlocui testarea obișnuită.","Controalele de urgență, coborârea de urgență și conceptele de salvare trebuie cunoscute și funcționale înainte de utilizare."],"h-gelaender":["Cum obțineți înălțimea suplimentară în coșul de lucru?","Un punct de montaj este chiar dincolo de atingerea ta.","Urcă-te pe gardul coșului.","Așezați o scândură pe balustradă.","Utilizați o platformă adecvată cu înălțime de lucru suficientă; nu te urca pe balustrade.","Urcarea gardului sau a cotelor improvizate pune în pericol protecția împotriva căderii."],"h-psaga":["Ce cerințe se aplică echipamentelor personale de protecție împotriva căderii?","Utilizați o platformă de lucru pentru care este prevăzut un sistem de reținere.","Orice punct de ancorare din afara coșului este întotdeauna suficient.","Respectați evaluarea riscurilor, informațiile producătorului și punctele de ancorare adecvate.","Nu utilizați nicio siguranță dacă coșul are balustradă.","Dacă și ce EIP este necesar este determinat de evaluarea riscurilor, etapa de construcție și instrucțiunile de operare."],"h-verfahren":["Se poate muta scena cu platforma ridicată?","Locul de muncă este la câțiva metri distanță.","Doar dacă modelul și condițiile de funcționare o permit conform instrucțiunilor producătorului.","Întotdeauna, atâta timp cât toată lumea ține.","Nu, niciodată indiferent de design și aprobarea producătorului.","Mișcarea în poziție ridicată depinde de dispozitiv și este permisă numai în condițiile de funcționare aprobate."],"h-kollision":["Ce trebuie organizat atunci când lucrați în apropierea macaralelor sau a altor utilaje?","Piesele în mișcare ar putea ajunge în coșul de lucru.","Nimic; coșul de lucru este întotdeauna vizibil.","Conduceți întotdeauna coșul de lucru peste celelalte mașini.","Coordonați zonele de lucru pentru a evita coliziunile sau punctele de prindere.","Funcționarea simultană a mașinii necesită procese de lucru coordonate și protecție împotriva coliziunilor sau blocării."],"h-einstieg":["Cum intri sau ieși din coșul de lucru?","Ajungi la coș la nivelul solului.","Urcați peste balustrada exterioară.","Prin accesul prevăzut într-o poziție sigură, conform instrucțiunilor de utilizare.","Printr-o scară plasată lângă ea cu brațul extins.","Accesul prevăzut și instrucțiunile producătorului trebuie respectate; Urcarea necontrolată peste prezintă riscul de cădere."],"h-defekt":["Instalația de oprire de urgență nu funcționează. ce faci?","Veți descoperi defectul în timpul inspecției.","Nu utilizați platforma și raportați defectul.","Continuați să lucrați dacă funcționează controalele normale.","Lipiți comutatorul, astfel încât nimeni să nu-l acționeze.","Defectarea unui dispozitiv de siguranță este un defect relevant pentru siguranță și împiedică funcționarea în siguranță."],"h-sicht":["Mișcarea de conducere nu poate fi văzută din cauza unui obstacol. Cum te descurci?","Ar trebui să mutați o scenă mobilă.","Conduceți încet, fără vizibilitate.","Bazează-te pe indicatorul de distanță.","Opriți mișcarea și asigurați vizibilitatea sau instrucțiunile sigure conform instrucțiunilor de operare.","Înainte de procedură, oamenii, obstacolele și căile de trafic trebuie supravegheate în siguranță."],"h-rettung":["Ce presupune planificarea implementării atunci când lucrați la înălțimi mai mari?","Scena este folosită într-o zonă îndepărtată.","Doar durata de lucru planificată.","Un concept de salvare adecvat cu persoane accesibile, instruite și proceduri de coborâre de urgență.","Presupunerea că pompierii va rezolva imediat orice problemă.","O salvare eficientă trebuie organizată în prealabil, chiar dacă controalele normale eșuează."],"k-befaehigung":["Ce este necesar pentru a opera o macara independent?","Un nou angajat ar trebui să preia munca la macara.","Adecvare și calificări necesare, instruire și misiunea corespunzătoare.","Permisul de conducere auto este suficient.","Vizionarea o dată este suficientă.","Lucrările cu macaraua pot fi atribuite numai persoanelor calificate și autorizate; Instruirea echipamentelor face parte din aceasta."],"k-funktionspruefung":["Ce este nevoie pentru a verifica macaraua înainte de începerea turei?","Preiei o macara de interior.","Citiți doar timpul de funcționare de pe plăcuța de identificare.","Verificați funcțiile relevante pentru siguranță și defectele vizibile conform instrucțiunilor de utilizare.","Testați macaraua cu sarcină maximă fără a verifica.","Controlul operațional obligatoriu servește la identificarea defectelor periculoase într-un stadiu incipient."],"k-traglast":["Care este semnificația capacității de încărcare admisă?","O sarcină trebuie ridicată.","Este o recomandare fără caracter obligatoriu.","Se aplică numai când cârligul este complet retras.","Capacitatea de sarcină admisă pentru condiția de funcționare respectivă nu trebuie depășită.","Sarcinile permise pentru anumite tipuri de macarale pot depinde de rază, poziția brațului și armament."],"k-personen":["Ce se aplică persoanelor aflate sub sarcini suspendate?","Sarcina este mutată peste o zonă de lucru.","Zona periculoasă trebuie menținută liberă; nimeni nu are voie să pășească sub sarcina suspendată.","O cască vă permite să stați direct sub ea.","Traversările scurte sunt permise dacă macaraua se mișcă încet.","Sarcinile suspendate prezintă risc de cădere și strivire; Oamenii trebuie ținuți în afara zonei periculoase."],"k-signale":["Nu poți vedea atacatorul și primești semnale contradictorii. ce faci?","Comunicarea este neclară.","Continuați ultima comandă de unitate.","Opriți mișcarea și clarificați clar comunicarea.","Reduceți sarcina mai repede, fără consultare.","Mișcările sigure ale sarcinii necesită semnale clare și comunicare clară."],"k-sicht":["Cine va oferi sprijin în timpul transportului dacă operatorul de macara nu poate vedea pe deplin traseul încărcăturii?","Un stâlp de sală ascunde poteca.","O persoană care trece fără acordul prealabil.","Nici unul; important doar cârligul.","O persoană potrivită, instruită, cu înțelegere clar agreată.","Dacă traseul de încărcare nu este vizibil, sunt necesare instrucțiuni adecvate sau o altă soluție sigură."],"k-ruck":["De ce ar trebui evitate mișcările sacadate ale macaralei?","O sarcină grea începe să se balanseze.","Acestea creează tensiuni dinamice suplimentare și pot destabiliza sarcina.","Practic reduc orice mișcare a pendulului.","Ele cresc întotdeauna capacitatea nominală de încărcare.","Forțele de accelerare și de frânare cresc efortul asupra macaralei și a curelelor."],"k-sperrbereich":["Ce ar trebui să verificați înainte de a balansa o încărcătură într-o zonă comună?","Alți angajați lucrează în apropiere.","Dacă sarcina se potrivește vizual cu macaraua.","Dacă zona periculoasă este securizată și nicio persoană nu este în pericol.","Dacă încărcătura poate fi transportată cât mai sus posibil deasupra tuturor.","Căile pivotante și de încărcare trebuie să fie libere de persoane neprotejate."],"k-stuetzen":["Ce este crucial pentru o macara mobilă cu stabilizatoare?","O macara este amplasată pe un teren parțial umplut.","Doar lățimea drumului.","Culoarea plăcilor suport.","Baza portantă, precum și suportul și distribuția sarcinii conform instrucțiunilor de instalare și ale producătorului.","Instalația are o influență semnificativă asupra stabilității, în special în condițiile schimbătoare ale solului."],"k-wetter":["O rafală de vânt face ca sarcina să se balanseze semnificativ. Ce este corect?","Lucrezi in aer liber.","Opriți mișcarea în siguranță și respectați condițiile de funcționare permise.","Accelerează rapid mișcarea.","Continuați să ridicați sarcina în ciuda depășirii limitelor producătorului.","Mișcările vântului și balansării pot destabiliza încărcătura și macaraua; Limitele de aplicare trebuie respectate."],"k-freileitung":["Ce se aplică la utilizarea macaralelor în apropierea liniilor electrice aeriene?","Brațul sau sarcina s-ar putea apropia de linie.","Cu o sarcină neconductivă, spațiile libere nu sunt importante.","Clarificați zona periculoasă și măsurile de protecție necesare cu cei responsabili înainte de a începe lucrul.","Bazați-vă doar pe reacția propriei macarale.","Există pericole de contact și declanșarea tensiunii; sunt necesare distanțe de protecție sigure sau alte măsuri."],"k-sichern":["Ce faci înainte de a părăsi macaraua?","Munca este întreruptă.","Lăsați încărcătura să atârne suspendată.","Lăsați macaraua nesupravegheată cu unitatea în funcțiune.","Coborâți sarcina în siguranță și asigurați macaraua conform instrucțiunilor de utilizare.","Sarcinile suspendate nu trebuie lăsate necontrolate; Macaraua și sarcina trebuie parcate în siguranță."],"k-lastanschlag":["De unde știi dacă slingul folosit este potrivit?","Sarcina trebuie ridicată cu ajutorul unei curele de ridicare.","În ceea ce privește marcarea, capacitatea de încărcare, starea și adecvarea pentru tipul de atașament.","Doar după culoarea curelei de ridicare.","Pentru că a fost deja folosit ieri.","Capacitatea de încărcare și starea trebuie să fie suficiente, ținând cont de condițiile de atașare."],"k-stopp":["O persoană intră în mod neașteptat pe calea de încărcare. ce faci?","Macaraua mută în prezent o încărcătură.","Opriți imediat mișcarea în siguranță și curățați zona periculoasă.","Dați doar un semnal de avertizare și continuați să conduceți.","Ridicați sarcina mai sus și treceți peste ea.","Oamenii trebuie protejați de mișcările încărcăturii; Dacă există un pericol imediat, mișcarea trebuie oprită."],"k-neuerkran":["Veți primi o macara cu un control necunoscut. Ce este corect?","Controalele sunt diferite decât înainte.","Încercați cheile obișnuite dacă bănuiți.","Permiteți altcuiva fără antrenament să conducă înainte.","Primiți instrucțiunile necesare legate de dispozitiv înainte de utilizarea independentă.","Chiar și operatorii de macarale cu experiență au nevoie de cunoștințe despre comenzile specifice utilizate, dispozitivele de protecție și limitele."],"a-kennzeichnung":["Cum știți capacitatea de încărcare admisă a unei sling?","Vrei să alegi o praștie.","Mirosul materialului.","Pe marcajul corespunzător, lizibil al capacității de încărcare și pe informațiile producătorului.","Despre durata de depozitare.","Capacitatea de încărcare admisă este determinată de etichetare și de condițiile de funcționare."],"a-sichtpruefung":["Observați o tăietură clară în cureaua de ridicare. Cum te descurci?","Banda ar trebui să transporte o sarcină.","Nu utilizați banda și trimiteți-o pentru testare sau respingere.","Acoperiți tăietura cu bandă adezivă.","Folosiți-l numai pentru sarcini deosebit de ușoare.","Slingurile textile deteriorate pot eșua și trebuie evaluate conform criteriilor de aruncare."],"a-neigungswinkel":["Ce se întâmplă dacă unghiul de înclinare al șuvițelor sling-ului este mai mare decât verticala?","Un cuier cu două fire se întinde mai mult.","Forțele firelor scad întotdeauna.","Forțele firelor rămân aceleași.","Forțele din fire cresc; Trebuie respectate unghiurile și capacitățile de sarcină admise.","Pe măsură ce răspândirea crește, forța de tracțiune pe toron de susținere crește."],"a-schwerpunkt":["De ce trebuie să cunoașteți centrul de greutate al încărcăturii?","Sarcina este acumulată neuniform.","Pentru ca sarcina să rămână stabilă atunci când este ridicată și să nu se răstoarne necontrolat.","Pentru a selecta culoarea chingilor.","Pentru ca sarcina să poată fi rotită mai repede.","Punctele de atașare nefavorabile sau poziția centrului de greutate pot duce la răsturnare, alunecare sau pante înclinate."],"a-kantenschutz":["O curea de ridicare se află pe o margine ascuțită a componentei. Ce ar trebui făcut?","Componenta trebuie ridicată.","Ridicați rapid sarcina înainte ca centura să fie deteriorată.","Utilizați o protecție adecvată pentru margini și verificați tipul de atașament.","Curățați suprafața de încărcare numai cu o cârpă.","Marginile ascuțite pot deteriora fibrele de susținere; echipamentul de slinging trebuie protejat corespunzător."],"a-haken":["La ce acordați atenție când atașați o praștie?","Folosești un cârlig de marfă.","Așezați chinga pe partea laterală a vârfului cârligului.","Țineți clapeta de siguranță deschisă în permanență.","Încărcați cârligul așa cum este prevăzut în baza cârligului și respectați dispozitivele de siguranță.","Sarcina inadmisibilă pe vârful cârligului și lipsa de fixare pot duce la desprinderea acestuia."],"a-knoten":["Puteți scurta o curea de ridicare care este prea lungă cu un nod?","Lungimea opririi nu se potrivește.","Nu; Utilizați numai un tip de sling adecvat și aprobat sau un echipament de sling adecvat.","Da, dacă nodul este tras foarte strâns.","Da, atâta timp cât încărcătura este în prezent staționară.","Nodurile pot slăbi semnificativ slingurile textile și nu sunt permise ajustări improvizate de lungime."],"a-probehub":["De ce o sarcină este ridicată inițial cu grijă?","Vrei să transporti în siguranță.","Pentru ca ea să poată face naveta cât mai repede posibil.","Pentru a verifica poziția chingilor, stabilitatea și centrul de greutate.","Deoarece capacitatea de încărcare crește automat.","O primă cursă controlată ajută la detectarea opririlor incorecte și a pozițiilor instabile ale sarcinii."],"a-lastweg":["Unde au voie să stea oamenii în timp ce încărcătura este transportată?","Sarcina este deplasată cu o macara.","Direct sub sarcină cu o cască de protecție.","Pe povara dacă pot rezista.","În afara zonei periculoase și nu sub sarcini suspendate.","Chiar și cu atașarea atentă, există totuși pericole legate de căderea sau balansarea sarcinilor."],"a-haende":["Cum eviți rănile prin zdrobire la înțărcare?","Sarcina se apropie de suprafața de sprijin.","Țineți mâinile și picioarele departe de zona de zdrobire și folosiți ajutoare adecvate.","Țineți sarcina cu mâna goală.","Stați între sarcină și perete pentru a corecta poziția.","Între sarcină și suport apar puncte de prindere periculoase."],"a-vierstraenge":["Ce se aplică distribuției sarcinii pe o suspensie cu patru picioare fără compensare a sarcinii?","Este atașată o sarcină rigidă.","Toate cele patru fire poartă în mod inevitabil aceeași cantitate.","Fără dovada distribuției uniforme, capacitatea portantă nu poate fi utilizată ca estimare generală pentru patru toroane încărcate egal.","Unghiul de înclinare este atunci irelevant.","Încărcarea inegală a firelor este posibilă cu sarcini rigide; Proiectarea și capacitatea de încărcare admisă trebuie să țină cont de acest lucru."],"a-chemikalien":["Ce se aplică atunci când folosiți chingi textile în contact cu substanțe chimice?","Lucrezi cu un lichid necunoscut.","Culoarea benzii își arată în mod fiabil durabilitatea.","Fiecare banda textila este rezistenta la toate substantele chimice.","Verificați durabilitatea și informațiile producătorului; Nu folosiți mijloace nepotrivite.","Substanțele chimice pot ataca chingile și, neobservate, le pot reduce capacitatea portantă."],"a-aufbewahrung":["Cum se depozitează slingurile după utilizare?","Misiunea s-a terminat.","Curățat, uscat și protejat împotriva deteriorării conform specificațiilor producătorului.","Blocat pe pământ sub o sarcină neprotejată.","Pe orice cârlig ascuțit de exterior.","Depozitarea adecvată previne uzura prematură și facilitează inspecția vizuală."],"a-auswahl":["Ce ar trebui luat în considerare în special pentru sarcinile sensibile sau cu muchii ascuțite?","O componentă vopsită a mașinii trebuie mutată.","Doar viteza de transport.","Slinguri adecvate și măsuri de protecție pentru suprafața de încărcare și margini.","Indiferent de sarcină, întotdeauna același cablu de oțel.","Tipul de atașament și materialul trebuie să se potrivească cu geometria, suprafața și pericolul."],"a-abstimmung":["Operatorul de macara nu vă vede. Cum dai instructiuni?","Ești desemnat ca atacator.","Faci cu mâna în voie până când începe o mișcare.","Dai doar un apel și pleci.","Prin semne clar agreate sau prin alte comunicări de încredere.","Atacatorii și operatorii de macara trebuie să comunice clar; Dacă nu este clar, mișcarea trebuie oprită."],"b-qualifikation":["De ce are nevoie o persoană pentru a opera în siguranță un excavator hidraulic în timpul funcționării?","O persoană nouă ar trebui să preia lucrările pe șantier.","Calificări corespunzătoare, instrucțiuni legate de dispozitiv și misiunea necesară.","Doar permis de conducere auto.","Doar o observare rapidă a operațiunii.","Angajatorul trebuie să asigure calificările necesare și să instruiască operatorul în mod corespunzător pentru sarcină."],"b-pruefung":["Ce este inclus în inspecția zilnică a mașinii?","Preiei un excavator.","Verificați culoarea vopselei și tapițeria scaunelor.","Inspecție vizuală și teste funcționale conform instrucțiunilor de utilizare, de exemplu pentru scurgeri și deteriorare.","Deplasați brațul la viteză maximă până când se oprește.","Deteriorarea sistemului hidraulic, a șasiului și a dispozitivelor de siguranță poate duce la accidente grave."],"b-leitungen":["Ce trebuie știut despre conductele subterane înainte de excavare?","Ar trebui să sapi un șanț.","Doar adâncimea aproximativă a gropii de excavare planificată.","Culoarea marcajelor de deasupra solului este suficientă.","Clarificați locația posibilelor linii și determinați măsuri adecvate de securitate și explorare.","Conductele de electricitate, gaz sau apă pot avea consecințe care pun viața în pericol dacă sunt deteriorate."],"b-schwenkbereich":["Cum protejezi oamenii din zona de balansare a excavatorului?","Ridicați material cu brațul.","Izolați sau asigurați zona periculoasă și țineți oamenii departe.","Înainte de a pivota, mișcați încet lopata.","Conduceți peste zona deasupra capetelor.","Suprastructura pivotantă și uneltele creează pericole de strivire și impact."],"b-boeschung":["Ce este important atunci când lucrați lângă marginea unei gropi de excavare?","Excavatorul stă pe teren stabilit sau umplut.","Numai adâncimea de săpare determină amplasarea admisă.","Acordați atenție capacității portante și asigurării marginii, precum și distanțelor necesare conform evaluării riscului.","Conduceți cât mai aproape de margine pentru a economisi distanța.","Dacă există spațiu liber suficient sau teren stabil, terasamentul se poate defecta și mașina poate cădea."],"b-standsicherheit":["De ce panta și terenul sunt cruciale pentru utilizare?","Şantierul este în pantă.","Mașina este la fel de stabilă pe orice suprafață.","Trenurile de rulare pe șenile elimină orice risc de răsturnare.","Denivelările și pantele pot afecta stabilitatea; Respectați limitele de aplicare.","Stabilitatea și siguranța la răsturnare depind de podea, echipament, sarcină și poziția mașinii."],"b-wechselgeraet":["Ce verificați după ce schimbați o cupă de excavator folosind o cuplare rapidă?","A fost instalat un nou atașament.","Dacă este corect blocat și asigurat conform instrucțiunilor de utilizare.","Doar dacă culoarea lopeții se potrivește.","Dacă sistemul hidraulic funcționează cât mai silențios.","Încuietori defecte pot cauza căderea atașamentelor."],"b-heben":["La ce ar trebui să acordați atenție atunci când ridicați o sarcină care atârnă liber cu un excavator?","Excavatorul este utilizat pentru operațiuni de ridicare.","Doar forța obișnuită de săpat este decisivă.","Respectați sarcina de ridicare admisă, punctele de atașare adecvate și dispozitivele de protecție prescrise.","Sarcina poate fi agatată de dinții găleții.","Ridicarea este permisă numai în condițiile de funcționare prevăzute, cu echipamente adecvate."],"b-rueckwaerts":["Trebuie să dai înapoi, dar nu poți vedea calea. Ce este corect?","Alți muncitori sunt în apropiere.","Conduceți cu grijă, fără vizibilitate.","Doar claxonați și continuați să conduceți.","Opriți, asigurați vizibilitatea și zona periculoasă sau organizați instrucțiuni adecvate.","Marşarierul nu trebuie să pună în pericol oamenii; vizibilitatea limitată necesită măsuri suplimentare."],"b-kabel":["Boom-ul s-ar putea apropia de o linie electrică aeriană. ce faci?","Lucrezi pe un șantier îngust.","Clarificați în prealabil zona periculoasă și măsurile de protecție adecvate cu cei responsabili.","Ignorați linia dacă brațul este vopsit.","Mișcați brațul doar foarte repede.","Pericolele electrice apar din contact și erupție; sunt necesare distanțe de siguranță și măsuri de protecție."],"b-verlassen":["Cum parcați excavatorul înainte de a pleca?","Ia o pauză.","Lăsați brațul să plutească liber.","Puneți echipamentul de lucru în siguranță și asigurați mașina împotriva mișcării și utilizării neautorizate.","Lăsați motorul pornit și cabina deschisă.","Echipamentul de lucru coborât și protecția împotriva mișcărilor neintenționate reduc riscul de accidente."],"b-hydraulik":["Observați ulei hidraulic sub presiune mare pe o conductă deteriorată. Ce este corect?","O linie curge.","Simțiți scurgerea cu mâna.","Atașați o nouă clemă sub presiune.","Opriți mașina în siguranță, lăsați presiunea să fie redusă și aranjați ca reparațiile să fie efectuate de personal specializat autorizat.","Lichidul hidraulic sub presiune mare poate provoca leziuni grave; nu verificați niciodată scurgerile manual."],"b-unterbau":["Care este pericolul de a conduce pe suprafețe instabile?","Pământul este moale după ploaie.","Aparatul se poate scufunda, aluneca sau răsturna.","Unitatea devine automat mai lată.","Acest lucru face raza de pivotare mai sigură.","Capacitatea de încărcare insuficientă poate afecta semnificativ stabilitatea și siguranța la conducere."],"b-arbeitsgeraet":["Poate cineva să lucreze sub un instrument ridicat?","O persoană vrea să controleze ceva sub lopată.","Da, când motorul este la ralanti.","Nu, nu fără sprijinul și asigurarea în siguranță necesare a echipamentului de lucru.","Da, dacă persoana poartă o cască de protecție.","Echipamentele hidraulice se pot scufunda; Lucrările de întreținere necesită echipament de lucru sigur."],"b-geraeteart":["Treci de la un excavator hidraulic la un încărcător frontal. Ce se cere?","Comportamentul de funcționare și de mișcare este diferit.","Aceeași încălțăminte.","Un test drive fără instrucțiuni.","Calificarea sau instruirea necesară pentru noul tip de mașină.","Calificarea trebuie să corespundă tipului de mașină utilizată și cerințelor operaționale specifice."],"g-neigung":["Conduceți un stivuitor încărcat pe o pantă. Ce este important?","Traseul are o pantă clară.","Ghidați întotdeauna sarcina în jos, chiar dacă este grea.","Ghidați încărcătura în sus și respectați instrucțiunile operaționale pentru conducerea în pantă.","Indiferent de direcția de mers, ridicați furca la maximum.","La pante si coborari, sarcina trebuie purtata intotdeauna in sus; Vehiculul și instrucțiunile de utilizare trebuie respectate."],"g-gabelabsenken":["De ce trebuie coborâtă furca la parcare?","Stivuitorul este parcat pentru o pauză.","Pentru ca alții să poată folosi furca pentru a urca.","Pentru ca furca sa ramana mai vizibila de la distanta.","Astfel încât ridicarea sarcinii să nu prezinte un risc inutil de împiedicare sau rănire.","Dispozitivele de manipulare a sarcinii coborâte reduc riscul de accidente din cauza furcilor proeminente sau neasigurate."],"g-fahrerwechsel":["Un coleg ar dori să împrumute stivuitorul. Ce trebuie să fie prezent?","Colegul are doar permisiunea verbală de la tine.","El trebuie să aibă calificările necesare și un mandat de companie.","Propria ta misiune i se aplică automat și lui.","Un permis de conducere auto privat este suficient pentru orice afacere.","Conducerea independentă este legată de adecvarea personală, de pregătire, de calificări și de misiunea operațională."],"g-ladungssicherung":["Un palet conține cutii vrac, stivuite. Ce este corect?","O cutie de carton poate cădea în timpul conducerii.","Asigurați încărcătura împotriva alunecării și căderii înainte de transport.","Conduceți încet doar pe un teren deosebit de neuniform.","Compensați cutiile libere cu o poziție mai înaltă a furcii.","Sarcina trebuie să fie stabilă și asigurată împotriva căderii înainte de a fi transportată cu utilajul de transport uzinal."],"g-bodenbelastung":["În fața ta este o pătură cu capacitate de încărcare limitată. Cum te decizi?","Traseul duce peste un nivel intermediar.","Atenție doar la greutatea camionului fără sarcină.","Clarificați sarcina admisibilă pe podea pentru stivuitoare și încărcături.","Conduceți cu impuls, astfel încât tavanul să fie sub sarcină pentru o perioadă mai scurtă de timp.","Ceea ce este relevant este stresul total real asupra zonei, inclusiv vehiculul, sarcina și influențele dinamice."],"g-verkehrswege":["O potecă marcată îți traversează calea. Ce este corect?","Pietonii pot accesa oricând trecerea.","Puteți revendica oricând prioritate cu claxonul.","Aveți voie să treceți peste marcaj fără a fi observat.","Reglați-vă viteza, acordați atenție pietonilor și continuați să conduceți doar când poteca este liberă.","Căile de circulație trebuie conduse cu atenție față de oameni; Semnele de avertizare nu înlocuiesc vizibilitatea sigură și traseul liber."],"g-parkbremse":["Parcați un stivuitor pe un teren plan. Ce include asta?","Doriți să părăsiți scaunul șoferului pentru câteva minute.","Parcați, aplicați frâna de parcare și asigurați-vă împotriva utilizării neautorizate.","Lăsați vehiculul numai în poziție neutră.","Lăsați furca la înălțimea capului, astfel încât nimeni să nu o atingă.","Înainte de a pleca, camionul trebuie oprit în siguranță și asigurat împotriva mișcării accidentale."],"g-typenschild":["Ce informații sunt obligatorii când vine vorba de sarcina pe un stivuitor?","Vrei să ridici o mașină grea.","Capacitatea de încărcare estimată în funcție de dimensiunea vehiculului.","Informațiile producătorului în diagrama de sarcină sau capacitatea de încărcare.","Greutatea ultimului palet transportat.","Sarcina admisă este determinată de informațiile producătorului și depinde, printre altele, de centrul de încărcare și de înălțimea de ridicare."],"g-tore":["Te apropii de un pasaj jos cu un stivuitor. Ce verifici?","Există o sarcină uriașă pe vehicul.","Dacă trecerea inclusiv sarcina și atașarea este posibilă în siguranță.","Doar înălțimea suportului furcii fără sarcină.","Dacă poți trece mai repede înainte de a se închide poarta.","Înainte de treceri, trebuie luate în considerare înălțimea și lățimea liberă, precum și dimensiunile încărcăturii și vehiculului."],"g-reifen":["În timpul verificării zilnice, găsiți o anvelopă grav deteriorată. ce faci?","Daunele relevante pentru siguranță sunt vizibile pe anvelopă.","Conduceți încet până la programarea obișnuită de întreținere.","Creșteți presiunea în anvelope și continuați să conduceți.","Nu puneți vehiculul în funcțiune și raportați avaria.","Anvelopele deteriorate pot afecta stabilitatea și manevrabilitatea; defectul trebuie clarificat înainte de utilizare."],"h-absperren":["Angajații trec pe lângă platforma dvs. de lucru. Ce este necesar?","Există pericolul căderii sculelor.","O zonă adecvată de protecție sau restricționată sub locul de muncă.","Doar o notificare când treci prima oară.","Depozitați uneltele cât mai departe de marginea coșului.","O zonă de lucru aflată sub stații de lucru înalte trebuie să fie asigurată împotriva pericolului cauzat de căderea pieselor."],"h-werkzeuge":["Cum transportați uneltele în coșul de lucru?","Sunt necesare mai multe unelte mici la înălțime.","Așezați-le lejer pe balustradă, astfel încât să fie la îndemână.","Depozitați și asigurați astfel încât să nu cadă și să nu împiedice funcționarea.","Atașați-l pe exteriorul balustradei în buzunar.","Obiectele libere pot cădea și pot pune oamenii în pericol; este necesară stocarea securizată."],"h-abstuetzung":["Un suport stă pe un capac de canal. Ce trebuie verificat?","Vrei să ridici platforma.","Doar asigurați-vă că capacul este uscat.","Dacă sarcina poate fi absorbită în siguranță în acel moment.","Dacă celelalte suporturi nu trebuie folosite.","Subsolul și zonele de contact trebuie să poată absorbi în siguranță forțele de susținere; Acoperirile trebuie evaluate separat."],"h-notaus":["Când trebuie utilizat dispozitivul de oprire de urgență?","Apare imediat o mișcare periculoasă.","Doar la sfârșitul unei ture obișnuite.","Pentru oprirea în pericol acut conform instrucțiunilor de utilizare.","Ca înlocuitor pentru coborârea planificată.","Oprirea de urgență este folosită pentru a preveni pericolul, nu controlul obișnuit sau oprirea normală."],"h-schraegstellung":["Avertismentul de înclinare a scenei răspunde. Cum reactionezi?","Mașina se află pe o suprafață înclinată.","Ignorați avertismentul la înălțimi mici de lucru.","În ciuda avertismentului, conduceți până la cea mai înaltă poziție de ridicare.","Te oprești și aduci scena într-o stare de siguranță conform instrucțiunilor producătorului.","Avertismentele de înclinare pot indica o stabilitate inadecvată; mișcările ulterioare nu trebuie să sporească pericolul."],"h-umgebung":["Ce trebuie organizat la instalarea în apropierea unei zone de trafic?","Vehiculele pot atinge scena.","Protecție împotriva coliziunilor și ghidare adecvată a traficului.","Rotiți coșul de lucru cât mai departe posibil peste drum.","Doar un apel de avertizare înainte de a porni.","Platformele aeriene de lucru trebuie protejate împotriva coliziunilor cu utilizatorii drumului; instalația trebuie asigurată corespunzător."],"h-ueberlast":["Avertizarea de suprasarcină din coș este declanșată. ce faci?","Au fost invitate instrumente suplimentare.","Terminați lucrul la viteză mai mare.","Stabiliți încărcarea permisă a coșului și urmați instrucțiunile producătorului.","Opriți permanent semnalul de avertizare.","Sarcina maximă admisă pe coș, inclusiv persoane și materiale, nu trebuie depășită."],"h-quetschen":["Conduci coșul aproape sub un acoperiș. Care pericol este deosebit de important?","A mai rămas puțin spațiu deasupra coșului.","Prindere sau strivire între coș și structură.","Că motorul consumă mai mult combustibil.","Că direcția de mers se inversează întotdeauna automat.","Spațiile înguste deasupra sau lângă coșul de lucru pot provoca răni grave prin strivire."],"h-stromausfall":["Scena rămâne la o înălțime mare fără un drive principal. Ce este corect?","Controlul normal al coșului nu mai răspunde.","Cobori pe braț fără siguranță.","Aștepți până la sfârșitul turei fără a fi informat.","Inițiați salvarea pregătită folosind oameni instruiți și coborârea de urgență.","Salvarea în siguranță trebuie planificată pentru întreruperi; Oamenii instruiți trebuie să cunoască funcțiile de urgență."],"h-transportstellung":["Cum pregătești scena pentru un transport?","Platforma de lucru aeriană este încărcată pe un vehicul adecvat.","Aduceți brațul și platforma în poziția de transport conform instrucțiunilor de utilizare.","Legați platforma cât mai departe posibil.","Lăsați suporturile extinse, astfel încât să ocupe mai mult spațiu.","Poziția de transport prescrisă și asigurarea încărcăturii se bazează pe producător și pe specificațiile de transport."],"k-bremsprobe":["Ce arată un test funcțional al frânei macaralei înainte de utilizare?","Vrei să poți ține o încărcătură în siguranță.","Dacă frâna se oprește și menține mișcarea conform intenției.","Doar dacă iluminarea cabinei funcționează.","Dacă cârligul poate ține automat o sarcină.","Înainte de utilizare, funcțiile relevante pentru siguranță trebuie verificate conform specificațiilor."],"k-schraegzug":["Puteți trage o sarcină lateral într-un unghi cu macaraua?","Cârligul nu este vertical deasupra sarcinii.","Da, dacă macaraua mai are rezervă de sarcină.","Nu, sarcinile nu trebuie trase folosind trageri diagonale nepermise.","Da, dacă chingile sunt deosebit de scurte.","Tragerea în diagonală poate provoca mișcări necontrolate și solicitarea suplimentară a macaralei și a curelelor."],"k-verhakt":["O sarcină atârnă de substructură. Ce este corect?","Rezistenta se simte la ridicare.","Continui să ridici până când iese.","Mutați sarcina în lateral, sacadat.","Te oprești și vei înlătura în siguranță prinderea sau blocajul.","Încărcăturile blocate nu trebuie smulse prin forță, deoarece pot apărea forțe inacceptabile."],"k-anzuheben":["Ce verificați când ridicați pentru scurt timp o sarcină suspendată pentru prima dată?","Sarcina se ridică la câțiva centimetri de la sol.","Indiferent dacă atârnă în echilibru și oprirea este sigură.","Dacă o persoană se poate pune direct sub sarcină.","Dacă macaraua devine mai stabilă prin întoarcerea rapidă.","Ridicarea controlată scurtă este utilizată pentru a verifica atașamentul, echilibrul și comportamentul sigur al încărcăturii."],"k-lastweg":["Unde ar trebui să fie calea de transport a unei încărcături cu macara?","Mai multe locuri de muncă se află sub posibila cale de încărcare.","Dacă este posibil, deasupra posturilor de lucru ocupate.","Pe o cale planificată, clară, fără oameni în pericol.","Întotdeauna în diagonală prin zona cea mai aglomerată.","Traseele de încărcare trebuie organizate astfel încât oamenii să nu fie periclitate de încărcăturile suspendate."],"k-signalverlust":["Conexiunea radio cu mareșalul se întrerupe. ce faci?","Nu puteți vedea calea de încărcare în sine.","Continuați mișcarea încet.","Te balansezi experimental în direcția anterioară.","Opriți mișcarea până când există o înțelegere clară și sigură.","Dacă există o lipsă de comunicare, este posibil ca mișcarea confuză a sarcinii să nu continue."],"k-haken":["Cârligul de siguranță nu se închide sigur. Ce este corect?","În timpul inspecției, se observă o închidere defectuoasă.","Eroarea trebuie corectată profesional înainte de utilizare ulterioară.","Legați strâns clema cu o strângere de cablu.","Folosești cârligul doar pentru încărcături ușoare.","Dispozitivele de fixare defecte pe cârligele de încărcare pot duce la desprinderea chingilor și trebuie remediate."],"k-zugrichtung":["Ce este important pentru suportul vertical al unei sarcini?","Sarcina trebuie ridicată de pe o mașină.","Cârligul macaralei trebuie aliniat deasupra centrului de greutate al încărcăturii.","Cârligul trebuie poziționat cât mai lateral posibil.","Sarcina trebuie împinsă înainte de ridicare.","Un efect de forță care este cât mai vertical posibil deasupra centrului de sarcină evită forțele laterale nepermise și balansarea necontrolată."],"k-wartung":["Pe macara se observă un zgomot de măcinat neobișnuit. Cum te descurci?","Zgomotul apare la ridicare.","Acoperiți zgomotul printr-o viteză mai mare.","Opriți operațiunile în siguranță, raportați defecțiunile și rezolvați-le.","Continuați să lucrați fără preaviz până la pauză.","Schimbările vizibile pot indica daune relevante pentru siguranță și necesită o inspecție."],"k-absetzen":["Ce trebuie să fie garantat la coborârea sarcinii unei macarale?","O sarcină grea este poziționată pe o suprafață.","Sarcina poate sta neasigurată pe o suprafață înclinată.","Slingurile sunt îndepărtate în timp ce încă plutește.","Sarcina este stabilă și asigurată împotriva răsturnării sau rulării.","Sarcina poate fi eliberată din dispozitivul de slingare numai după ce a fost așezată în siguranță și stabilitatea a fost stabilită."],"l-schwerpunkt":["De ce trebuie cunoscut centrul de greutate înainte de a lovi?","O mașină cu formă asimetrică urmează să fie transportată.","Pentru ca sarcina să rămână cât mai echilibrată posibil la ridicare.","Pentru ca slingurile să poată fi alese atât cât se dorește.","Astfel încât capacitatea de încărcare admisă să nu joace un rol.","Poziția centrului de greutate influențează distribuția sarcinii și echilibrul sigur la ridicare."],"l-etikett":["O curea de ridicare nu are o etichetă care poate fi citită cu capacitatea de încărcare. Ce este corect?","Marcajul a devenit de nerecunoscut.","Estimați capacitatea de încărcare în funcție de culoare.","Nu utilizați cureaua de ridicare până când adecvarea acesteia nu a fost demonstrată în mod clar.","Utilizați cureaua o singură dată pentru sarcini mici.","Pentru curele sunt necesare marcaje adecvate; Capacitatea de transport inexplicabilă exclude selecția în siguranță."],"l-kantenschutz":["O bandă textilă se află peste o margine ascuțită de oțel. Ce este necesar?","Sarcina are margini ascuțite.","Trageți de bandă cât mai strâns posibil fără protecție.","Efectuați cursa mai repede.","Folosiți protecție adecvată pentru margini sau alt echipament adecvat de slinging.","Marginile ascuțite pot deteriora sau tăia curele textile; este necesară o protecție adecvată."],"l-spreizwinkel":["Cum afectează un unghi de înclinare mai mare sarcina pe chingi?","O sarcină este ridicată folosind două frânghii înclinate.","La unghiuri mai puțin favorabile, forțele din fire pot crește.","Forțele firelor dispar.","Unghiul nu are nicio influență asupra tensiunii.","Cu un unghi de oprire mai puțin favorabil, forțele pe șuviță pot crește; Trebuie respectate tabelele cu capacitatea de încărcare."],"l-knoten":["O frânghie poate fi scurtată după cum se dorește folosind un nod?","Coarda este prea lungă pentru sarcina planificată.","Da, un nod strâns îmbunătățește capacitatea de încărcare.","Nu, utilizați numai metode aprobate de scurtare și ancorare.","Da, dacă nodul este fixat cu bandă.","Nodurile nepermise slăbesc chingile și le modifică capacitatea de încărcare admisă."],"l-zeichen":["Ce se aplică comunicării cu persoana care operează macaraua?","Calea de încărcare este parțial ascunsă.","Mai multe persoane dau semnale diferite în același timp.","Se folosesc semnale clare, convenite anterior.","Comunicarea nu este niciodată necesară cu macaralele radio.","Semnele clare și responsabilitățile clare previn mișcările incorecte periculoase."],"l-sichtpruefung":["Când ar trebui verificate chingile pentru defecte vizibile?","Vrei să folosești un lanț de praștie.","Înainte de utilizare, acordați atenție oricăror daune vizibile din exterior.","Doar dacă s-a întâmplat deja un accident.","Doar o singură dată la prima achiziție.","Înainte de fiecare utilizare trebuie evaluată starea de siguranță de lucru; Deteriorările vizibile împiedică utilizarea în siguranță."],"l-drehung":["O sarcină ridicată începe să se rotească necontrolat. ce faci?","Sarcina se deplasează pe traseul de sarcină.","Îți pui mâna între încărcătură și perete.","Te pui sub povară și te ții de ea.","Vă păstrați distanța și lăsați mișcarea să se oprească într-un mod controlat.","Mișcările necontrolate ale sarcinii creează pericole de strivire și impact; Oamenii trebuie să părăsească zona periculoasă."],"l-ablegen":["Când pot fi scoase chingile de pe sarcină?","Încărcătura este așezată pe stâlpi.","Dacă sarcina este stabilă și asigurată împotriva răsturnării sau rostogolirea.","De îndată ce atinge solul pentru prima dată, indiferent de poziția sa.","În timp ce încă plutește pentru a economisi timp.","Slingurile pot fi îndepărtate numai după ce au fost așezate în siguranță și stabil."],"l-ketten":["O praștie de lanț are o verigă foarte îndoită. ce faci?","Deteriorarea este vizibilă chiar înainte de ridicare.","Înfășurați zona deteriorată cu sârmă.","Scoateți lanțul din utilizare și verificați-l profesional.","Ridicați sarcina doar la jumătate la fel de mare.","Vergile de lanț deformate sunt daune vizibile care pot împiedica utilizarea în siguranță."],"b-einweiser":["Ce este important atunci când vizibilitatea de la excavator este limitată?","O parte a clădirii ascunde zona de conducere.","Măsuri vizuale adecvate sau instrucțiuni și comunicare clară.","Ai grijă doar la capotă.","Conduceți prin zona de pivotare, deși este invizibil.","Dacă vizibilitatea este restricționată, pericolele trebuie prevenite prin măsuri organizatorice și tehnice suplimentare."],"b-aushub":["Unde poate fi depozitat materialul excavat lângă o groapă de construcție?","Marginea gropii nu trebuie supusă unui risc suplimentar.","Îngrămădiți direct pe margine, astfel încât căile de acces să rămână libere.","Depozitați la o distanță suficient de sigură și conform specificațiilor de șantier.","Așezați pe un sprijin liber fără alte teste.","Materialul excavat poate pune în pericol terasamentele și sprijinirea din cauza sarcinilor suplimentare; Distanțele de siguranță trebuie menținute."],"b-personen":["Oamenii au voie să rămână în zona de balansare în timp ce excavatorul este în mișcare?","O persoană dorește să măsoare în timp ce face panoramă.","Da, atâta timp cât poartă cască de protecție.","Da, dacă excavatorul se balansează încet.","Nu, zona periculoasă trebuie să fie liberă înainte de mișcare.","Există riscul de strivire gravă și răni la impact în zona de pivotare; zona trebuie menținută liberă."],"b-ladung":["Cum transportați materialul în siguranță cu un încărcător pe roți?","O lopată plină ar trebui să fie condusă prin curte.","Cu o poziție joasă de transport adecvată și o cale liberă.","Cu lopata ridicata pentru o mai buna vizibilitate.","Cu ușile deschise și unghi puternic de direcție.","O poziție de transport adecvată reduce riscul de răsturnare și îmbunătățește stabilitatea conducerii."],"b-anbaupruefung":["Ce verificați după cuplarea unui atașament?","A fost atașată o lopată nouă.","Doar curățenia vopselei.","Încuierea sigură și funcționează conform instrucțiunilor de utilizare.","Doar dacă dispozitivul arată la fel din exterior.","Blocările incorecte ale cuplelor rapide pot duce la eliberarea neintenționată a atașamentelor."],"b-einstieg":["Cum intri în siguranță în cabina excavatorului?","Treptele sunt murdare după ploaie.","Urcă-te în cabină prin braț.","Urcă-te pe omizi dintr-un singur salt.","Folosiți treptele și mânerele desemnate și curățați treptele murdare.","Urcările adecvate și punctele de prindere sigure reduc riscul de alunecare și cădere."],"b-graben":["Un perete de șanț prezintă crăpături și se prăbușește. Ce este corect?","Lucrezi chiar lângă șanț.","Opriți lucrul și puneți cei responsabili să securizeze groapa de excavare.","Pur și simplu conduceți mai aproape de margine pentru a închide șanțul.","Adânciți și mai mult șanțul fără protecție.","Fisurile și mișcările solului pot indica instabilitate și necesită o evaluare suplimentară a siguranței."],"b-betanken":["La ce acordați atenție când realimentați o mașină de terasament?","Rezervorul este aproape gol.","Asigurați motorul și sursele de aprindere conform instrucțiunilor producătorului și evitați scurgerea.","Umpleți întotdeauna cu benzină sau motorină în cabină.","Fumați în timpul realimentării când nu este vânt.","Riscurile de incendiu și de mediu la manipularea combustibilului necesită măsuri de protecție adecvate."],"b-laufwerk":["De ce șenilele și trenul de rulare trebuie verificate în mod regulat?","Observați vibrații neobișnuite în timpul conducerii.","Pentru ca mașina să se poată mișca mai repede.","Deoarece deteriorarea poate afecta ghidarea sigură și stabilitatea.","Pentru că munca este întotdeauna permisă fără inspecție vizuală.","Deteriorarea unității poate afecta manevrabilitatea, stabilitatea și funcționarea în siguranță."],"b-einweisen":["Ce este necesar atunci când lucrați în apropierea traficului pietonal public?","Un excavator lucrează direct pe marginea unui trotuar.","Pietonii ar trebui să se deplaseze ei înșiși prin zona de balansare.","Doar lipiți un semn pe lopată.","Izolați eficient zona periculoasă și direcționați traficul în siguranță.","Terții nu trebuie să intre în zona de pericol a mașinilor de terasament; Sunt necesare bariere adecvate și trasee de trafic."],"g2-fahrweg":["Există lichid vărsat pe drumul din față. Cum te descurci?","Stivuitorul ar conduce direct peste zona alunecoasă.","Opriți conducerea și asigurați-vă sau îndepărtați punctul de pericol.","Conduceți peste loc cât mai repede posibil cu furca ridicată.","Sperați în anvelope mai uscate și continuați să conduceți neschimbat.","Rutele contaminate pun în pericol stabilitatea și trebuie asigurate corespunzător înainte de a circula pe ele."],"g2-sichtladung":["Un palet înalt blochează vederea din față. Ce este corect?","Trebuie să conduci până la o zonă de depozitare și nu poți vedea traseul.","Ridicați paletul până când puteți vedea dedesubt.","Conduceți numai folosind metode adecvate și sigure, cum ar fi mersul înapoi cu o vedere clară.","Puteți circula în continuare pe șosea fără stâlp indicator sau vedere liberă.","Direcția de mers și vizibilitatea trebuie să permită observarea în siguranță a rutei de circulație; Încărcăturile nu trebuie să înlocuiască inspecția vizuală."],"g2-fussgaengerstop":["Un pieton se oprește chiar lângă stivuitor. ce faci?","Persoana se află în raza posibilă de conducere și pivotare.","Depășiți pietonul accelerând scurt.","Conduceți pe lângă persoana cu sarcina ridicată.","Opriți-vă și continuați să conduceți doar la o distanță sigură.","Oamenii trebuie să rămână în afara zonei periculoase; Dacă este necesar, călătoria trebuie întreruptă."],"g2-hubmast":["Observați o conductă hidraulică deteriorată pe catargul de ridicare. Ce se aplică?","Uleiul hidraulic curge vizibil din utilaj.","Scoateți stivuitorul din funcțiune și raportați deteriorarea.","Verificați scurgerea manual în timpul ridicării.","Ridicați doar sarcini mai mici până la sfârșitul schimbului.","Deteriorarea hidraulică poate duce la mișcări necontrolate; utilizarea în siguranță nu este garantată până la testare."],"g2-lagerregal":["Vrei să depozitezi un palet pe un raft. Ce verifici mai intai?","Nivelul raftului este ridicat și capacitatea de încărcare trebuie menținută.","Împingeți paletul pe raft cât mai repede posibil.","Verificați dacă compartimentul pentru rafturi, greutatea încărcăturii și spațiul liber de depozitare sunt adecvate.","Estimați greutatea totală numai pe baza numărului de cutii.","Rafturile și echipamentele de transport trebuie să se potrivească cu situația de încărcare și depozitare."],"g2-batterieschaden":["O baterie a unui stivuitor este deteriorată extern. Ce este corect?","Înainte de încărcare, se observă fisuri sau fluid neobișnuit.","Acoperiți deteriorarea cu bandă adezivă și încărcați imediat.","Lasă o altă persoană să încarce bateria fără a o verifica.","Nu încărcați sau utilizați și informați specialiștii responsabili.","Bateriile deteriorate prezintă pericole electrice și chimice și necesită o evaluare profesionistă."],"g2-fahrerkabine":["Ce se aplică obiectelor libere din zona șoferului?","Uneltele sunt pe podea, lângă pedalele de control.","Îndepărtați obiectele și păstrați zona de operare liberă.","Țineți unealta doar cu un picior în timp ce conduceți.","Ascundeți piesele libere sub scaunul șoferului.","Obiectele libere pot bloca pedalele și pot afecta funcționarea în siguranță a vehiculului."],"g2-uebergabe":["Preiei un stivuitor după o schimbare de tură. Ce include asta?","Un coleg a folosit ultima dată vehiculul.","Să presupunem că colegul a preluat toate verificările.","Efectuați inspecția necesară și consultați defecțiunile cunoscute.","Începeți călătoria fără să vă uitați la mașină.","Persoana care preia trebuie să se asigure că este într-o stare sigură înainte de utilizare."],"g2-transportsicherung":["Un obiect înalt este liber pe palet. Cum te comporti?","Sarcina se poate răsturna înainte la frânare.","Portați furca deosebit de sus, astfel încât sarcina să rămână stabilă.","Doar luați curbele încet, mergeți drept mai repede.","Montați sarcina într-o manieră stabilă și asigurați-o împotriva răsturnării sau căderii.","Încărcăturile libere trebuie stabilizate înainte de transport, astfel încât mișcările de frânare și de conducere să nu provoace căderea acestora."],"g2-arbeitsende":["Ce este important cu un stivuitor nesupravegheat?","Îți închei tura și părăsești zona.","Parcați vehiculul în siguranță și asigurați-l împotriva deplasării și a utilizării neautorizate.","Lăsați cheia, astfel încât colegii să poată găsi mașina.","Lăsați furculița la nivelul ochilor, astfel încât să fie vizibilă.","Parcarea în siguranță include manipularea sarcinii reduse și protecție împotriva mișcării și a punerii în funcțiune neautorizate."],"g2-bremsweg":["De ce trebuie să acordați o atenție deosebită distanței de frânare sub sarcină?","Stivuitorul transportă mărfuri grele printr-un culoar al depozitului.","Frânați întotdeauna mai târziu cu o sarcină mare decât fără sarcină.","Reglați viteza la condițiile de vizibilitate, sol și încărcare.","La frânare, ridicați brusc sarcina pentru a decelera mai bine.","Masa și starea drumului influențează distanța de oprire; viteza adaptată este cheia."],"g2-rampe":["Ce verificați înainte de a urca o rampă abruptă?","Traseul poate fi prea abrupt pentru vehicul.","Conduceți pe rampă cu viteză maximă, indiferent de panta.","Conduceți peste marginea rampei cu sarcina ridicată.","Verificați panta admisă și modul de funcționare sigur din specificațiile vehiculului.","Pot fi utilizate numai rampe în limitele operaționale prevăzute; Instrucțiunile de operare și controlul sarcinii sunt decisive."],"g2-zinke":["Un palet este mai lat decât distanța la furcă. Ce trebuie luat în considerare?","Intenționați să preluați o sarcină neobișnuit de mare.","Reglați distanța furcii și punctele de montare pentru a se potrivi sarcinii.","Folosiți un singur dinți dacă sarcina este prea largă.","Ridicați sarcina într-un unghi până când ajunge în poziția corectă.","Absorbția uniformă și adecvată a sarcinii reduce alunecarea și răsturnarea."],"g2-betriebsanweisung":["Ce rol joacă reglementarea operațională a traficului?","Zonele marcate cu sens unic și pietonale se aplică în depozit.","La stivuitoare se aplică doar regulile drumului public.","Urmați rutele specificate și regulile de circulație.","Ignorați marcajele odată ce vehiculul este încărcat.","Rutele companiei și regulile de siguranță protejează traficul cu stivuitoare și oamenii care merg pe jos."],"g2-nothalt":["Direcția reacționează neobișnuit în timpul conducerii. Ce este corect?","Vehiculul nu mai poate fi controlat ca de obicei.","Conduceți la viteze mai mari pentru a face direcția mai receptivă.","Compensați eroarea cu abateri de direcție deosebit de mari.","Opriți-vă într-un loc sigur și verificați vehiculul.","Defectarea direcției pune în pericol ghidarea sigură; mașina nu trebuie să continue să funcționeze necontrolat."],"g2-anschlagkette":["Doriți să mutați o sarcină suspendată liber cu un stivuitor. Ce se aplică?","O sarcină ar trebui să atârne de un cârlig de sub furci.","Numai cu un dispozitiv omologat și echipament adecvat pentru transportul sarcinii.","Orice lanț va funcționa dacă sarcina nu este grea.","Prindeți lanțul direct între ambele furci.","Sarcinile suspendate liber schimbă stabilitatea; Sunt necesare aprobări ale producătorului și facilități adecvate."],"g2-rollenlast":["O componentă cilindrică se află neasigurată pe un palet. ce faci?","În timpul transportului, sarcina se poate rostogoli.","Apropiați-vă de palet în mod deosebit sacadat.","Asigurați componenta împotriva rulării înainte de ridicarea paletului.","Poziționați dinții suficient de sus încât componenta să nu fie vizibilă.","Sarcinile rotunde sau rulante necesită protecție fiabilă împotriva schimbărilor de poziție."],"g2-pruefplakette":["De unde știi dacă stivuitorul poate fi folosit?","Există un autocolant de inspecție lipit de mașină.","Orice autocolant înlocuiește întotdeauna inspecția vizuală zilnică.","Lipsa spațiului liber poate fi înlocuită cu o conducere atentă.","Pe lângă verificarea vehiculului, trebuie luate în considerare starea validă a testului și aprobarea de funcționare.","Testele recurente și controalele operaționale zilnice îndeplinesc diferite funcții de siguranță."],"g2-licht":["Iluminatul din depozit s-a stins brusc. Ce este corect?","Nu mai puteți vedea în siguranță obstacolele din cale.","Opriți conducerea până când vizibilitatea sigură este garantată.","Măriți viteza de conducere pentru a părăsi zona întunecată.","Continuați să conduceți cu furcile ridicate fără inspecție vizuală.","Un traseu care nu poate fi trecut cu vederea în siguranță nu trebuie parcurs fără măsuri eficiente de siguranță."],"g2-ueberhang":["O sarcină se extinde cu mult dincolo de partea laterală a furcii. Ce verifici?","Doriți să transportați paletul printr-o poartă îngustă.","Compensați proiecția laterală cu o curbă rapidă.","Evaluați spațiul liber, stabilitatea și capacitatea de încărcare admisă înainte de a conduce.","Conduceți sarcina la viteza maximă, indiferent de forma acesteia.","Conversoarele cresc riscul de coliziune și pot modifica stabilitatea și spațiul necesar pentru trafic."],"g2-wartungsbereich":["Există bariere în fața unei zone de întreținere. Cum te comporți?","Ruta dumneavoastră obișnuită este temporar închisă.","Mutați scurt barierele și treceți neobservat.","Conduceți direct prin zona de lucru sub sarcină.","Observați închiderea și alegeți o rută alternativă aprobată.","Zonele izolate nu pot fi pătrunse sau traversate fără permisiune."],"g2-bremsprobe":["Când are sens un test funcțional al frânei de serviciu?","Pregătiți stivuitorul înainte de muncă.","Ca parte a inspecției necesare înainte de utilizare.","Efectuați numai după un accident grav.","Doar dacă camionul a ajuns deja la viteză mare.","Funcționalitatea instalațiilor relevante pentru siguranță este verificată înainte de utilizare."],"g2-fahrzeuganhaenger":["Vrei să tragi o remorcă cu un stivuitor. Ce se cere?","Compania plănuiește transportul cu încărcătură atașată.","Legați fiecare remorcă de o furcă fără a verifica.","Respectați aprobarea producătorului, cuplarea adecvată și sarcina de tracțiune admisă.","Doar crește presiunea în anvelope și pleacă.","Operarea trenului este posibilă numai în siguranță, în conformitate cu specificațiile tehnice și cu o conexiune adecvată."],"g2-rueckfahrt":["Ce este important la mers înapoi cu stivuitorul?","Există o zonă confuză pe culoarul depozitului.","Priviți întotdeauna numai în oglinda retrovizoare, indiferent de împrejurimi.","Conduceți fără vizibilitate atâta timp cât claxonul a fost apăsat o dată.","Observați în siguranță traseul și zona oamenilor și, dacă este necesar, instruiți-le.","Marșarierul necesită o vedere clară sau măsuri de siguranță suplimentare eficiente."],"g2-lastentnahme":["Scoți un palet de pe un raft înalt. Ce este corect?","Este posibil ca paleta să nu fie centrată.","Ridicați sarcina în siguranță și stabilizați-o înainte de coborâre.","Lăsați paletul să se balanseze în lateral în timp ce îl trageți afară.","Verificați sub paletul ridicat pentru a vedea dacă este deteriorat.","Ridicarea și coborârea controlate previne căderea sarcinilor și mișcările periculoase."],"h2-absenkweg":["De ce trebuie să rămână liberă zona de sub o platformă de lucru aeriană?","Coșul este coborât și materialele sunt plasate sub el.","Apăsați materialele în jos cu coșul.","Urmăriți doar zona piciorului operatorului.","Evitați riscul de strivire și coliziune la coborâre.","Zona de coborâre nu trebuie să conțină persoane sau obstacole care ar putea rămâne prinse."],"h2-transporthoehe":["Cum deplasați o scenă mobilă pe un pasaj jos?","Spațiul liber este mai mic decât brațul extins.","Așezați platforma într-o poziție de transport adecvată, conform instrucțiunilor de utilizare.","Lăsați brațul întins și deplasați-vă sub tavan.","Apăsați coșul pe partea laterală a tocului ușii.","Pentru mișcările de deplasare, înălțimea totală și poziția de transport trebuie să se potrivească cu specificațiile producătorului și cu trecerea."],"h2-bodenoeffnung":["Există o deschidere nesigură în podea lângă scenă. Cum reactionezi?","Un punct de conducere sau de sprijin este situat lângă deschidere.","Așezați un suport direct pe marginea deschiderii.","Schimbați locul de instalare sau verificați profesional capacitatea de încărcare și asigurarea.","Acoperiți doar punctul de pericol cu ​​o cutie de carton.","Deschiderile și zonele de margine pot eșua sub sarcini de sprijin și trebuie luate în considerare în mod eficient."],"h2-rettungsperson":["De ce o a doua persoană trebuie să fie familiarizată cu procedura de salvare?","Un operator ar putea deveni incapacitat la vârf.","Astfel că munca în coș poate avea loc în general fără securitate.","Pentru ca scena să poată fi operată mai repede decât este permis.","Pentru ca o salvare sigură să poată fi inițiată în caz de urgență.","Un concept de salvare trebuie să ia în considerare asistența de la sol în cazul unei defecțiuni sau a unei urgențe."],"h2-werkzeugabwurf":["Ce se aplică instrumentelor la altitudine mare?","O unealtă slăbită ar putea cădea peste marginea coșului.","Asigurați uneltele astfel încât să nu pună în pericol pe nimeni și să nu cadă.","Pur și simplu puneți unelte pe balustradă pentru a reduce sarcina.","Dacă este necesar, aruncați uneltele din coș.","Căderea obiectelor pune în pericol oamenii dedesubt; Materialul trebuie depozitat în siguranță."],"h2-trittstufe":["O cutie ar trebui să servească drept spațiu suplimentar pentru picioare în coș. Ce este corect?","Altfel, abia vei ajunge la locul de muncă.","Așezați cutia pe balustradă și urcați pe ea.","Nu urca pe cote improvizate; Utilizați echipament de lucru adecvat.","Încărcați intenționat coșul dincolo de înălțimea permisă.","Elevațiile improvizate afectează protecția împotriva căderii și nu sunt permise."],"h2-lastverteilen":["La ce ești atent când în coșul de lucru sunt mai multe persoane?","Două persoane lucrează în coș cu unelte grele.","Judecă sarcina numai pe baza dimensiunii sculei.","Depozitați uneltele grele direct pe balustrada de protecție.","Nu depășiți sarcina admisă a coșului, inclusiv persoane și unelte.","Capacitatea de încărcare admisă include toate persoanele, materialele și uneltele din coș."],"h2-abstuetzplatte":["Când sunt luate în considerare lamele suplimentare pentru suporturi?","Podeaua de instalare poate suporta doar o sarcină limitată.","Dacă acest lucru este necesar pentru distribuția sigură a sarcinii conform specificațiilor.","Pentru a aşeza suporturile cât mai aproape de marginea unei gropi de construcţie.","Pentru a utiliza o gamă mai lungă fără informații despre producător.","Sunt necesare zone de contact suficiente pentru forțele de sprijin sigure."],"h2-baugrube":["O scenă ar trebui să fie amplasată direct la marginea unei gropi de construcție. Ce verifici?","Subsolul ar putea ceda lateral din cauza gropii de excavare.","Extindeți suporturile în groapa de excavare.","Asigurați o distanță de siguranță suficientă și capacitatea portantă a subsolului.","Compensați riscul doar ridicând coșul încet.","Gropile de excavare pot afecta stabilitatea din cauza pantei și a defecțiunii subsolului."],"h2-witterung":["Glazura se instalează în timpul utilizării. Cum te comporti?","Suprafețele de control și zona de lucru devin netede.","Ridicați scena pentru a evita zăpada și gheața.","Ignorați avertismentele atâta timp cât platforma este aprinsă.","Întrerupeți lucrul și reevaluați condițiile de funcționare conform instrucțiunilor de utilizare.","Schimbările de vreme pot modifica răspunderea, operabilitatea și limitele de utilizare sigure."],"h2-aufbaukontakt":["O construcție din oțel limitează traseul coșului. Ce este important?","La ridicare există riscul de strivire între coș și suport.","Planificați mișcările astfel încât corpul și coșul să nu fie prinse.","Faceți călătoria mai repede, astfel încât coșul să treacă mai repede.","Împingeți construcția cu coșul în lateral.","Punctele de prindere dintre platformă și mediu necesită o observare atentă și o mișcare controlată."],"h2-sicherheitsabstand":["Când trebuie izolată zona periculoasă a unei etape?","Pe sub amplasament trece o rută de transport public.","Doar dacă un obiect a căzut deja.","Dacă terții ar putea fi periclitate prin mișcare sau căderea obiectelor.","Niciodată, deoarece coșul de lucru previne practic toate pericolele.","Zona de sub și de lângă scenă trebuie protejată împotriva pericolelor previzibile."],"h2-korbtor":["Ce se aplică ușii de intrare a coșului de lucru?","Sunteți deja la înălțimea de lucru.","Lăsați ușa deschisă ca să puteți ieși mai repede.","Legați ușa permanent deschisă cu o frânghie.","Țineți ușa închisă conform mecanismului de blocare furnizat.","Încuietorile prevăzute fac parte din măsurile de protecție împotriva căderii din cușca de lucru."],"h2-energieleitung":["Ce se aplică dacă o linie aeriană nu este oprită în siguranță?","Lucrezi cu platforma de lucru aeriană în apropierea lor.","Asigurați distanțele de siguranță specificate și măsurile de protecție necesare.","Mutați coșul chiar în fața liniei atâta timp cât nu este atins.","Aveți încredere în anvelopele din plastic și lucrați fără goluri.","Erupțiile electrice sunt posibile și fără contact direct; Sunt necesare distanțe de siguranță."],"h2-schwanken":["Coșul de lucru începe să se balanseze neobișnuit de puternic. Ce este corect?","Mișcarea nu mai este controlată.","Reajustați necontrolat cu contramișcări rapide.","Opriți mișcarea și verificați cauza sau condițiile de funcționare.","Adăugați oameni suplimentari în coș pentru a-l face mai greu.","Vibrațiile neobișnuite pot indica condiții de funcționare necorespunzătoare sau o defecțiune."],"h2-ladegeraet":["Un cablu de încărcare pentru treapta acţionată electric este deteriorat. ce faci?","La conectare, izolația deteriorată este vizibilă.","Atingeți deteriorarea cu mănuși umede.","Apăsați ștecherul în priză cât mai tare posibil.","Nu începeți procesul de încărcare și verificați cablul profesional.","Cablurile electrice deteriorate prezintă un risc de electrocutare și incendiu."],"h2-gelaenderanbau":["Poți să scoți singur o balustradă pentru a te apropia?","O componentă împiedică oamenii să se apropie de locul de muncă.","Nu modificați sau îndepărtați singur dispozitivele de protecție.","După ridicare, deșurubați balustrada și instalați-o mai târziu.","Continuați să lucrați fără balustradă atâta timp cât cineva stă lângă ea.","Dispozitivele de protecție structurală nu pot fi schimbate fără specificații permise și măsuri de înlocuire sigure."],"h2-lastkran":["Platforma poate fi folosită ca macara pentru a ridica o încărcătură?","Materialul trebuie transportat atârnat liber lângă coșul de lucru.","Ori de câte ori greutatea este mai mică decât greutatea corporală proprie.","Doar dacă producătorul și echipamentul permit în mod expres această utilizare specială.","Pur și simplu atașați un cârlig la balustradă și ridicați materialul.","Platformele aeriene de lucru nu sunt proiectate automat pentru lucrul cu macara sau sarcini suplimentare suspendate."],"h2-arbeitsvorbereitung":["Ce înseamnă pregătirea pentru o nouă locație?","Încă nu cunoașteți șantierul.","Doar estimați distanța până la cea mai apropiată parcare.","Indiferent de împrejurimi, extindeți-l complet imediat.","Evaluați pericolele, solul, căile de trafic, salvarea și adecvarea echipamentelor.","O evaluare a riscurilor legate de locație este o condiție prealabilă pentru condiții de funcționare sigure."],"h2-kabelschlaufe":["Un cablu de alimentare se află peste calea scenei. Ce este corect?","Cablul poate rămâne prins în timpul mișcării.","Eliberați drumul și protejați cablurile electrice de deteriorare.","Utilizați cablul cu roțile ca prag de drum.","Ridicați coșul fără a verifica suprafața podelei.","Cablurile care sunt trecute peste sau strivite pot cauza pericole electrice și mecanice."],"h2-leitungsnaehe":["Cine clarifică măsurile de protecție asupra unui sistem electric?","Platforma ar trebui să funcționeze aproape de echipamentele sub tensiune.","Persoana din coș decide doar cu ochii.","Implicați autoritățile responsabile și implementați măsuri de protecție coordonate.","Distanța va fi stabilită numai după începerea lucrărilor.","Lucrul în apropierea sistemelor electrice necesită măsuri de protecție planificate și coordonate."],"h2-funkkommunikation":["De ce trebuie să fie clare semnalele între podea și coș?","O persoană aflată la sol ajută la manevrare.","Pentru ca mai multe persoane să poată da instrucțiuni contradictorii în același timp.","Pentru ca coborârea de urgență să poată fi încercată fără instrucțiuni.","Astfel încât mișcările să fie efectuate numai după o comunicare clară.","Comunicarea clară reduce mișcările incorecte și coliziunile în timpul manevrelor."],"h2-neuebedienung":["Treci la un alt tip de etapă. Ce se cere?","Funcțiile de operare diferă semnificativ.","Instrucțiuni specifice dispozitivului înainte de utilizarea independentă.","Citind doar sigla companiei de pe dispozitiv.","Un test drive cu coșul deja extins fără instrucțiuni.","Calificarea singură nu înlocuiește instrucțiunile pentru tipul specific de dispozitiv."],"h2-steckanschluss":["Ce ar trebui să verificați înainte de a conecta un încărcător?","O platformă de lucru aeriană electrică trebuie încărcată.","Folosiți orice priză, indiferent de stare și siguranță.","Verificați conexiunea adecvată și cablul nedeteriorat conform instrucțiunilor producătorului.","Deconectați în mod regulat ștecherul în timpul încărcării.","Conexiunile electrice adecvate și intacte protejează împotriva șocurilor electrice și incendiilor."],"h2-absperrpersonal":["O persoană intră în zona izolată în timpul lucrărilor de ridicare. ce faci?","Puteți vedea o persoană direct sub coșul de lucru.","Continuați să conduceți dacă persoana poartă o cască de protecție.","Aruncați o unealtă în direcția lor ca semnal de avertizare.","Opriți mișcările periculoase și curățați zona.","O barieră nu înlocuiește observarea zonei periculoase în timpul funcționării."],"k2-arbeitsplanung":["Ce ar trebui să fie inclus în pregătirea muncii înainte de operarea macaralei?","Încărcarea, locația și ruta de transport nu au fost încă coordonate.","Ridicați mai întâi sarcina cea mai grea fără planificare ulterioară.","Marcați doar cel mai scurt traseu la etajul holului.","Clarificați în prealabil capacitatea de încărcare, curele, calea de încărcare și zona periculoasă.","O mișcare planificată a macaralei necesită o manipulare adecvată a sarcinii, rute sigure și măsuri de protecție coordonate."],"k2-hakenposition":["Cum este poziționat cârligul macaralei peste sarcină înainte de ridicare?","Punctele de atașare sunt sub macara.","Cât mai vertical posibil deasupra centrului de greutate conform opritorului.","Deplasați mult în lateral, astfel încât sarcina să intre mai repede.","În orice caz, la marginea exterioară a sarcinii, indiferent de centrul de greutate.","Aplicarea verticală a forței și punctele de ancorare adecvate reduc mișcarea laterală și mișcările necontrolate."],"k2-hakengabel":["Un cârlig de încărcare prezintă o deformare vizibilă. Ce se aplică?","Cârligul pare îndoit față de starea sa obișnuită.","Îndoiți deformația înapoi cu următoarea sarcină.","Opriți funcționarea macaralei și verificați cârligul de către un expert.","Atașați doar sarcini ușoare și continuați să lucrați.","Deformarea poate afecta siguranța cârligului; utilizarea ulterioară neautorizată nu este permisă."],"k2-zugueberlast":["Povara este mai grea decât se presupunea inițial. ce faci?","În timpul pregătirii apar noi informații despre greutate.","Înlocuiți rezerva de siguranță cu o ridicare mai rapidă.","Ignorați greutatea încărcăturii atașând-o la un alt punct.","Determinați sarcina reală și verificați din nou limitele de sarcină.","Ridicarea în siguranță necesită date de sarcină fiabile și respectarea tuturor capacităților de încărcare relevante."],"k2-arbeitskorb":["Un cârlig obișnuit de macara poate transporta cu ușurință oameni?","O persoană vrea să ajungă la un loc de muncă înalt.","Nu, transportul de pasageri necesită facilități și măsuri speciale permise.","Da, dacă persoana se ține de frânghia.","Da, de îndată ce accidentul vascular cerebral este efectuat deosebit de lent.","Transportul de persoane este permis numai în condiții speciale prevăzute în acest scop."],"k2-bruecke":["O macara pod se deplasează de-a lungul unei căi comune a halei. Ce este important?","Angajații rămân pe ruta de transport.","Conduceți cu încărcătura chiar deasupra capetelor angajaților.","Păstrați în mod eficient traseul de încărcare și zona de trafic clare și sigure.","Folosiți doar claxonul de avertizare în loc de măsuri suplimentare.","Persoanele aflate în pericol nu trebuie să se afle sub încărcături suspendate sau pe calea lor de transport."],"k2-zweitekrane":["Două macarale lucrează într-o zonă suprapusă. Ce este necesar?","Brațele sau încărcăturile se pot ciocni între ele.","Ambii operatori de macara lucrează în același timp fără acord prealabil.","Mișcările sunt accelerate în mod deliberat pentru a evita intersecțiile.","Coordonează operațiunile și ia măsurile adecvate pentru a preveni amenințările reciproce.","Zonele de lucru suprapuse necesită organizare operațională coordonată și garanții adecvate."],"k2-pruefbuch":["Care este semnificația inspecției recurente obligatorii ale macaralei?","Mașina este utilizată în mod regulat în operațiuni.","Acesta completează controlul operațional cu expertiza prescrisă.","Înlocuiește permanent orice inspecție vizuală înainte de începerea lucrărilor.","Este necesar doar după un accident.","Inspecțiile recurente și controalele operaționale în curs au sarcini diferite."],"k2-absetzflaeche":["Zona de plasare prevăzută este neuniformă. Cum te comporti?","Sarcina se poate răsturna atunci când este plasată.","Puneți sarcina pe un colț și lăsați-o să atârne neschimbată.","Pregătiți baze sau suprafețe adecvate, portante și stabile.","Puneți o persoană sub sarcină în timp ce coborâți.","Zonele de amplasare trebuie să susțină sarcina în siguranță și să prevină mișcările periculoase de răsturnare sau de rostogolire."],"k2-anfahrbereich":["Înainte ca macaraua să înceapă să se miște, există o persoană în zona de călătorie. ce faci?","Traseul este blocat de o persoană.","Împingeți persoana deoparte cu un scurt test de conducere.","Deplasați-vă folosind doar întrerupătorul de limită, fără inspecție vizuală.","Începeți mișcarea numai când zona periculoasă este liberă și sigură.","Conducerea și mișcările de pivotare nu trebuie să pună în pericol oamenii."],"k2-schlaffseil":["De ce cablul de ridicare nu ar trebui să devină necontrolat atunci când este așezat?","Sarcina este pornită, cârligul este mai coborât.","Pentru ca frânghia și cârligele să nu se blocheze sau să nu fie supuse încărcării necontrolate.","Astfel încât sarcina să poată fi apoi trasă lateral de frânghie.","Pentru ca chingile să se desprindă de cârlig.","Traseul necontrolat al cablurilor poate duce la încurcare și mișcări periculoase ale sarcinii."],"k2-pendel":["O încărcătură transportată începe să se balanseze. Ce este corect?","Sarcina se deplasează lateral mai mult decât era planificat.","Compensați cu contramișcări rapide și viteză maximă.","Reduceți mișcările într-o manieră controlată și calmează naveta fără persoane în zona periculoasă.","Țineți sarcina care se balansează cu mâinile goale.","Sarcinile oscilante pot afecta oamenii și instalațiile; mișcările calme reduc riscul."],"k2-funkakku":["Comanda radio a unei macarale are o baterie slabă. Ce se aplică?","Conexiunea se poate rupe în timpul ridicării.","Ridicați rapid o sarcină înainte ca controlul să se defecteze.","Dacă conexiunea se pierde, mutați sarcina trăgând de chingă.","Asigurați-vă o conexiune de control fiabilă înainte de utilizare.","Controlul și comunicarea fiabile sunt condiții prealabile pentru mișcările controlate ale macaralei."],"k2-mehrereanschlaeger":["Două persoane dau semnale diferite operatorului de macara în același timp. Ce este corect?","Semnele se contrazic.","Întrerupeți mișcarea și clarificați responsabilitatea clară.","Preferați semnul persoanei mai îndepărtate.","Continuați mișcarea în funcție de propriul sentiment.","Conducătorii de macara au nevoie de o comunicare clară și fără ambiguitate, mai ales atunci când rutele de încărcare sunt confuze."],"k2-endabschaltung":["De ce nu ar trebui folosit greșit un comutator de limită ca o limitare normală a cursei?","Sarcina este adesea mutată până la distanța maximă de ridicare.","Întrerupătoarele de limită permit în general o ridicare mai rapidă, fără vizibilitate.","Întrerupătoarele de limită sunt dispozitive de siguranță și nu înlocuiesc funcționarea controlată.","Ar trebui să fie loviți cât mai puternic cu fiecare lovitură.","Dispozitivele de siguranță servesc pentru a proteja împotriva pericolelor și nu trebuie să fie suprautilizate conform planului."],"k2-wetterbeobachtung":["Vântul crește semnificativ cu o suprafață mare de încărcare. Ce se cere?","O zonă mare de componentă acționează ca o velă.","Ridicați întotdeauna sarcina mai sus, astfel încât vântul să aibă mai puțin efect.","Înlocuiți chingile cu altele mai subțiri.","Evaluați vânt și limitele operaționale și ajustați ridicarea dacă este necesar.","Vântul poate genera forțe suplimentare semnificative și mișcări ale pendulului, în special cu sarcini de suprafață mare."],"k2-ortswechsel":["Ce este important atunci când mutați o macara mobilă într-o locație nouă?","Subsolul și condițiile de sprijin se schimbă.","Verificați locația suportului și suportul înainte de a ridica încărcătura din nou.","Aplicați setările din locația anterioară fără a verifica.","Reajustați suportul în timpul ridicării.","Fiecare locație de instalare poate avea condiții diferite de încărcare la sol și suport."],"k2-betriebsbereich":["O macara ar trebui să lucreze peste o stradă. Ce trebuie clarificat?","Terții ar putea intra în zona periculoasă.","Asigurați drumul doar cu un claxon de avertizare.","Blocări necesare, vot și măsuri de protecție în fața hub-ului.","Ridicați sarcina peste vehicule cât mai repede posibil, fără a o asigura.","Rutarea sigură a traficului previne riscurile nejustificate pentru terți din cauza încărcăturilor și a mișcărilor macaralei."],"k2-hochheben":["După ridicarea de probă, o sarcină atârnă clar strâmbă. Ce este corect?","Focalizarea a fost aparent greșită.","Continuați să ridicați astfel încât dezechilibrul să se corecteze singur.","Rugați o persoană să tragă sarcina înclinată.","Așezați sarcina în siguranță și verificați din nou atașamentul și centrul de greutate.","Ridicatorul de testare este utilizat pentru a detecta atașarea incorectă și pozițiile instabile ale încărcăturii înainte de transport."],"k2-schwebelast":["Puteți lăsa o încărcătură ridicată atârnată nesupravegheată?","Schimbul se termină, dar încărcătura este încă pe cârlig.","Nu, coborâți sarcina în siguranță și asigurați corect macaraua.","Da, dacă macaraua este blocată împotriva deplasării.","Da, atâta timp cât există un semn de avertizare pe sol.","În principiu, încărcăturile suspendate nu trebuie lăsate nesupravegheate."],"k2-mitnahme":["Un coleg vrea să meargă cu o macara. Ce se aplică?","Sarcina trebuie transportată într-un punct mai înalt.","Călăria este permisă dacă colegul poartă cască.","Oamenii nu pot fi transportați pe sau atașați la încărcături normale.","O plimbare este întotdeauna permisă atâta timp cât colegul este cunoscut de conducătorul macaralei.","Transportul persoanelor împreună cu încărcăturile creează riscuri semnificative de cădere și strivire."],"k2-warnsignal":["Un sistem de avertizare operațional de pe macara se defectează. Ce este corect?","Nu mai este posibil să furnizați un avertisment înainte de a pleca.","Ignorați sistemul când motorul este pornit.","Înlocuiți permanent avertismentul atingând carcasa.","Raportați o defecțiune legată de siguranță și întrerupeți operațiunile conform instrucțiunilor.","Dispozitivele de avertizare necesare trebuie să fie funcționale, astfel încât oamenii să fie protejați în timp util."],"k2-schneekante":["O macara mobilă trebuie sprijinită pe teren înghețat, denivelat. Ce se aplică?","Solul își poate pierde capacitatea portantă pe măsură ce se dezgheță.","Evaluați capacitatea de încărcare și situația de sprijin în condiții reale.","Pământul înghețat are întotdeauna orice capacitate portantă.","Așezați doar suporturi pe pietre mici.","Temperatura, umiditatea și structura subsolului influențează capacitatea portantă a locațiilor macaralei."],"k2-laufkatze":["Un cărucior se deplasează spre un obstacol. Cum te comporti?","Există un obiect în zona de conducere.","Împingeți încet obiectul cu sarcina.","Opriți mișcarea în timp util și îndepărtați obstacolul în siguranță.","Conduceți pe lângă obstacol cu ​​viteză crescută.","Mișcările macaralei trebuie ghidate astfel încât să nu apară ciocniri cu obstacole."],"k2-anschlagaufnahme":["Ar trebui să ridicați o încărcătură folosind un ochi nedesemnat. Ce este corect?","Ochiul ar putea fi destinat doar pentru montarea unui capac.","Fiecare ochi este potrivit pentru sarcina maximă a macaralei.","Încărcați ochiul doar cu două persoane în același timp.","Verificați capacitatea de încărcare și adecvarea punctului de ancorare înainte de utilizare.","Nu orice ochi existent este un punct de atașare stabil pentru încărcăturile macaralei."],"l2-seilbruch":["Un cablu de sârmă arată mai multe fire individuale rupte. Ce este corect?","Punctele de rupere sunt în zona cablurilor portante.","Nu continuați să utilizați un dispozitiv de ridicare și solicitați-l să fie evaluat profesional.","Îndoiți capetele firului înapoi cu mâinile goale.","Continuați să utilizați frânghia dacă sarcina este deosebit de ușoară.","Ruperea firelor poate fi un criteriu de eliminare; Corzile deteriorate trebuie evaluate profesional."],"l2-schaekel":["Ce este esențial atunci când folosiți o cătușe?","O cătușă leagă chinga și sarcina.","Înlocuiți șurubul cu orice cui.","Verificați capacitatea de încărcare adecvată, starea nedeteriorată și șuruburile corecte.","Estimați capacitatea de încărcare în funcție de culoare.","Cătușele trebuie să fie dimensionate corespunzător, utilizate complet și în direcția prevăzută de încărcare."],"l2-tragfaehigkeit":["Ce trebuie să luați în considerare atunci când utilizați mai multe fire?","Șuvițele rulează în unghi față de verticală.","Pur și simplu adăugați capacitatea de încărcare a fiecărei șuvițe după cum doriți.","Atârnați sarcina doar pe cea mai ușoară șuviță.","Luați în considerare capacitatea portantă a întregului tip de ancoră și unghi.","Unghiul de înclinare și numărul efectiv de fire influențează semnificativ sarcina admisă."],"l2-schweissnaht":["Un punct de ancorare improvizat poate fi sudat la o sarcină?","Nu există puncte de preluare adecvate desemnate pentru încărcătură.","Utilizați numai puncte de ancorare proiectate și aprobate corespunzător.","Orice cusătură de sudură este suficientă fără testare.","Introduceți un cârlig printr-o deschidere din tablă.","Punctele de ancorare trebuie dovedite a fi potrivite pentru forțele implicate în ridicare."],"l2-einseitig":["O sarcină este semnificativ mai grea pe o parte. Cum te descurci?","Centrul de greutate este în afara centrului geometric.","Lăsați toate șuvițele de aceeași lungime, indiferent de centrul de greutate.","Determinați centrul de greutate și reglați poziția în consecință.","Mai întâi ridicați sarcina la înălțimea maximă de ridicare.","Dacă centrul de greutate este decentrat, sarcinile se pot răsturna în mod neașteptat sau firele individuale pot fi supraîncărcate."],"l2-kettenriss":["Ce se aplică unei curele de lanț cu fisuri vizibile?","Există o fisură într-una dintre zale.","Marcați fisura cu vopsea și ridicați-o neschimbată.","Înfășurați legătura cu sârmă și reutilizați-o.","Scoateți imediat lanțul și informați persoana responsabilă.","Fisurile din zalele de lanț portante sunt daune relevante pentru siguranță și necesită scoaterea din funcțiune."],"l2-lastfuehrung":["Cum transportați o sarcină mare când există riscul de rotație?","În timpul ridicării, sarcina se poate balansa în lateral.","Utilizați dispozitive de ghidare adecvate și o distanță de siguranță.","Țineți sarcina direct între mâini în timp ce conduceți.","Treceți sub sarcină și aliniați-o de jos.","Ghidarea încărcăturii nu trebuie să facă ca mâinile sau corpurile să intre în zona periculoasă."],"l2-schnueren":["Ce este important atunci când atașați șireturile?","Slingul este ghidat în jurul unei componente.","Să presupunem aceeași capacitate de încărcare ca orice alt tip de ancoră.","Respectați caracterul adecvat al tipului de atașament și sarcina admisă conform marcajului.","Trageți slingul împreună în orice măsură, fără a verifica.","Tipul de atașament de dantelă poate modifica capacitatea de încărcare admisă și trebuie utilizat corect."],"l2-winkelmesser":["De ce nu poți ignora un unghi de fir plat?","Două linii de curățare merg aproape orizontal la sarcină.","Un unghi plat face automat șuvița mai puternică.","Sarcina este întotdeauna distribuită în mod egal, indiferent de unghi.","Forțele mari ale firelor pot depăși capacitatea de încărcare admisă.","Pe măsură ce unghiul față de verticală crește, tensiunile asupra șuvițelor cresc."],"l2-heisse-last":["Ce trebuie să verificați dacă există o încărcătură fierbinte?","O piesă din oțel a fost recent tratată termic.","Respectați limitele de temperatură ale curelelor și selecția adecvată.","Fiecare sling textil poate rezista la orice temperatura.","Etichetarea nu contează când este cald.","Temperatura poate afecta capacitatea de încărcare admisă a chingilor."],"l2-abstand":["Puteți pune degetele sub sarcină când o așezați?","Sarcina trebuie să aterizeze pe o suprafață cu precizie milimetrică.","Da, dacă purtați mănuși de lucru.","Nu, păstrați distanța și folosiți ajutoare adecvate.","Da, dacă mișcarea macaralei este deosebit de lentă.","Părțile corpului dintre sarcină și bază pot rămâne prinse."],"l2-verbindung":["O verigă de legătură a lanțului de curățare nu este blocată. Ce se aplică?","Elementul de fixare lipsește.","Folosiți șurubul fără încuietoare când nimeni nu vă privește.","Sigilați elementul cu bandă adezivă.","Nu loviți până când dispozitivul de fixare nu este fixat corespunzător.","Elementele de legătură trebuie să fie asigurate complet și în conformitate cu proiectarea lor."],"l2-lasthaken":["Ce verifici atunci când agățați de cârligul macaralei?","Mai multe chingi ar trebui să fie ghidate în cârlig.","Asigurați o potrivire sigură și adecvarea cârligelor și suspensiei.","Puneți curele pe vârful cârligului.","Înlocuiți dispozitivul de blocare cu cârlig cu o prindere de cablu.","Forța trebuie aplicată așa cum este prevăzut în zonele desemnate."],"l2-fasern":["O chingă de ridicare prezintă aspățări severe și deteriorarea fibrelor. Ce este corect?","Fibrele de susținere sunt vizibil deteriorate.","Acoperiți deteriorarea cu un alt nod.","Separați cureaua de ridicare și verificați-o de către un specialist.","Apoi ridicați sarcina mai repede.","Fibrele portante deteriorate pot reduce semnificativ capacitatea portantă a unei curele de ridicare."],"l2-anheben":["Ce se aplică imediat după primul centimetru de ridicare?","Sarcina tocmai se ridică de pe bază.","Trageți încărcătura la înălțimea maximă fără control.","Verificați sub sarcină dacă curelele sunt tensionate.","Verificați poziția opririi, echilibrul și comportamentul de mișcare.","O ridicare de testare controlată face posibile instabilități vizibile înainte de transportul suplimentar."],"l2-lastgewichte":["Greutatea încărcăturii este necunoscută. Ce este corect?","Componenta nu are marcaj de greutate.","Determinați greutatea încărcabilă înainte de a selecta chingile.","Estimați greutatea pe baza culorii încărcăturii.","Utilizați orice sling de lungime dublă.","Fără o greutate cunoscută sau determinată în mod fiabil, adecvarea chingilor nu poate fi verificată cu certitudine."],"l2-lose-teile":["Există unelte libere pe sarcina care trebuie ridicată. ce faci?","Uneltele pot cădea la ridicare.","Țineți uneltele cu o mână când conduceți.","Îndepărtați sau fixați eficient obiectele libere înainte de a le ridica.","Ridicați încărcătura puțin mai repede, astfel încât să nu alunece nimic.","Obiectele libere pot cădea și pot pune în pericol oamenii din zonă."],"l2-wind":["O sarcină mare este atașată în cazul vântului puternic. Ce se aplică?","Componenta oferă vântului o suprafață mare de atacat.","Ridicați sarcina fără a lua în considerare mișcările de balansare.","Persoanele suplimentare ar trebui să țină direct sarcina.","Evaluați condițiile vântului și abțineți-vă de la ridicare dacă situația este nesigură.","Forțele vântului pot afecta ghidarea sarcinii și stabilitatea în timpul transportului."],"l2-unterlage":["De ce sunt importante documentele adecvate la înțărcare?","O încărcătură rotundă s-ar rostogoli pe pământ.","Așezați încărcătura ferm în jos și asigurați-o împotriva rulării, dacă este necesar.","Lăsați încărcătura direct pe chingi.","Împingeți documentele sub încărcătură numai după ce au fost așezate.","Suporturile adecvate previn răsturnarea și mișcările nedorite la așezare."],"l2-transportweg":["Ce trebuie coordonat înainte ca încărcătura să fie transportată?","Sarcina este mutată pe mai multe zone de lucru.","Doar durata estimată a hub-ului.","Calea de încărcare sigură, comunicare și bariere necesare.","O persoană ar trebui să arate drumul sub încărcătură.","Transportul încărcăturilor necesită căi de trafic sigure și o coordonare clară."],"l2-schutzschlauch":["La ce ar trebui să acordați atenție atunci când utilizați chingi cu furtun de protecție?","O bandă se află pe o margine aspră.","Orice cârpă subțire de pânză înlocuiește protecția adecvată a marginilor.","Un furtun de protecție înlătură orice limită de sarcină admisă.","Selectați echipamentul de protecție în funcție de adecvarea și cerințele de aplicare.","Echipamentul de protecție trebuie să se potrivească cu materialul, marginea și sarcina prevăzută."],"l2-reinigung":["O curea de ridicare a fost contaminată cu o substanță chimică necunoscută. Ce este corect?","Banda nu mai poate fi evaluată clar.","Opriți utilizarea și clarificați compatibilitatea sau starea profesională.","Curățați cu orice solvent și continuați imediat ridicarea.","Ignorați substanța chimică în timp ce banda este uscată.","Substanțele chimice pot afecta rezistența chingilor textile."],"l2-aufhaengung":["Ce verificați dacă există mai multe fire pe legătura suspensiei?","Două fire sunt așezate împreună într-o suspensie.","O șuviță se poate muta în vârful cârligului după bunul plac.","Toate elementele de conectare trebuie să fie adecvate și aranjate conform prevederilor.","Un inel cu o fisură poate fi folosit pentru sarcini mici.","Elementele de oprire și de legătură trebuie să fie portante și aranjate corect."],"l2-einweiserrolle":["Ce se aplică dacă atacatorul și operatorul de macara nu au linie vizuală?","Un purtător blochează vederea punctului de picătură.","Coordonează apelând mai multe persoane fără responsabilitate.","Mutați sarcina pe baza zgomotului fără instrucțiuni.","Organizați o comunicare clară și sigură și opriți-o dacă nu este clară.","Lipsa vizibilității trebuie compensată printr-o coordonare eficientă și o comunicare sigură."],"l2-ausserbetrieb":["O praștie deteriorată a fost rezolvată. Ce altceva este important?","Acesta rămâne liber accesibil alături de resurse gata de utilizare.","Asigurați-vă împotriva utilizării accidentale ulterioare și informați persoana responsabilă.","Returnați produsul nemarcat în inventar.","Folosiți-l din nou numai atunci când transportați o încărcătură deosebit de ușoară.","Slingurile aruncate trebuie protejate în mod fiabil înainte de utilizare ulterioară."],"b2-schwenkradius":["De ce este critică raza de balansare din spate a unui excavator?","Coada se deplasează pe o zonă limitată de lucru.","Terții pot fi prinși de suprastructura oscilantă.","Raza de balansare nu are nicio influență asupra persoanelor de lângă mașină.","Spatele se mișcă întotdeauna numai în direcția de mers.","La pivotare, în spatele mașinii apare și o zonă periculoasă."],"b2-verkehrseinweiser":["Cum este asigurată o mișcare de conducere când vizibilitatea este întunecată?","Un excavator trebuie să manevreze în spatele unui obstacol.","Conduceți fără să vedeți semnalele semnalizatorului.","Dacă este necesar, organizați instrucțiuni adecvate cu o comunicare clară.","Asigurați-vă marșarierul doar claxonând o dată.","Rutele confuze necesită măsuri eficiente pentru a preveni coliziunile și blocarea."],"b2-standplatz":["Ce se aplică unui stand de excavator pe o pantă?","Podeaua este înclinată și poate fi alunecoasă.","Mașina se poate extinde cât dorește cu orice înclinare.","Așezați întotdeauna excavatorul pe un strat liber de pământ.","Verificați stabilitatea și limitele de funcționare ale mașinii înainte de utilizare.","Panta și subsolul au o influență semnificativă asupra stabilității."],"b2-oberleitung":["De ce trebuie planificată distanța brațului de liniile electrice?","Brațul se poate apropia de cablu atunci când se rotește.","De asemenea, declanșarea electrică este posibilă fără contact direct.","Doar găleata poate conduce electricitatea, nu brațul.","Cu solul uscat, fiecare distanță este automat sigură.","Limitele de utilizare și distanțele de protecție trebuie clarificate înainte de abordarea sistemelor electrice."],"b2-fremdperson":["Un trecător intră în șantier în zona de panning. Ce este corect?","Persoana stă brusc lângă cupa excavatorului.","Ridicați lopata și balansați-o peste persoana.","Opriți imediat mișcarea și curățați zona.","Continuați să urmăriți persoana din fereastra laterală.","Persoanele aflate în zona periculoasă nu trebuie să fie puse în pericol de mișcările de lucru."],"b2-parkstellung":["Cum se asigură o mașină de terasament după terminarea lucrărilor?","Excavatorul rămâne nesupravegheat pe șantier.","Lăsați lingura la înălțimea capului.","Lăsați motorul să funcționeze nesupravegheat.","Puneți jos echipamentul de lucru, asigurați mașina și împiedicați utilizarea neautorizată.","Parcarea adecvată reduce mișcarea accidentală și accesul neautorizat."],"b2-eigenlast":["De ce sunt esențiale limitele echipamentului atunci când ridicați cu un excavator?","O sarcină grea urmează să fie ridicată pe braț.","În caz contrar, stabilitatea și capacitatea de încărcare admisă pot fi depășite.","Orice mașină poate ridica orice sarcină atâta timp cât se potrivește cupa.","Numai lungimea frânghiei de sling determină riscul.","Informațiile privind capacitatea de ridicare și încărcare depind de echipament și de situația aplicației."],"b2-untergrundhohlraum":["Podeaua de deasupra unui subsol vechi ar putea fi goală. ce faci?","Ar trebui să conduceți excavatorul în zonă.","Traversați locul cu impuls maxim.","Clarificați capacitatea de încărcare și posibilele cavități înainte de a continua.","Pur și simplu puneți o sarcină grea pe suprafață.","Cavitățile se pot prăbuși sub greutatea mașinii și pot provoca prăbușirea mașinii."],"b2-feuchtigkeit":["După ploi abundente, terasamentul devine moale. Ce este corect?","Un excavator lucrează lângă marginea terasamentului.","Mutați mașina mai aproape de margine pentru a crește raza de acțiune.","Ignorați modificările până la sfârșitul turei.","Reevaluați solul și condițiile de stabilitate.","Pătrunderea umidității poate modifica capacitatea portantă și stabilitatea terasamentelor."],"b2-bodenprobe":["De ce trebuie verificate planurile conductelor înainte de excavare?","Cablurile ar putea trece pe sub excavația planificată.","Astfel încât să poată fi identificate linii și să fie planificate măsuri de securitate adecvate.","Astfel, excavarea poate fi efectuată mai rapid, independent de sistemele terțe.","Deoarece mașinile nu trebuie folosite niciodată lângă cabluri.","Liniile de alimentare subterane necesită o clarificare fiabilă a locației înainte de lucrările de excavare."],"b2-maschinenzugang":["Ce se aplică atunci când intrați și coborâți din mașina de terasament?","Mașina se află pe teren accidentat.","Glisați în jos conducta hidraulică din cabină.","Folosiți pașii desemnați și asigurați-vă o poziție sigură.","Sari pe brațul pivotant în timp ce mașina funcționează.","Urcările sigure și punctele de oprire adecvate reduc riscul de cădere și strivire."],"b2-kupplung":["Cum verificați un nou buldoexcavator după instalare?","Cupa este conectată prin cuplarea rapidă.","Judecă lingura doar vizual de la o distanță mai mare.","Treceți direct sub lingura ridicată.","Asigurați blocarea corectă și pașii de control prescriși.","Atașamentele care sunt blocate incorect se pot desprinde și pot pune oamenii în pericol."],"b2-hydraulikwartung":["De ce conductele hidraulice nu pot fi deschise sub presiune?","Un furtun trebuie înlocuit.","Lichidul care scapă poate provoca răni grave din cauza presiunii ridicate.","Presiunea împiedică întotdeauna scurgerea uleiului.","O linie deschisă poate fi verificată în siguranță cu mâinile.","Fluidul de înaltă presiune poate pătrunde în țesut și necesită o reducere sigură a presiunii."],"b2-fahrweg":["Trebuie să conduci peste un pod temporar de construcție. Ce verifici?","Podul este proiectat doar pentru anumite sarcini.","Dacă culoarea podului se potrivește cu mașina.","Capacitatea de încărcare și adecvarea pentru greutatea și dimensiunile mașinii.","Doar dacă o mașină ușoară a circulat deja pe pod.","Structurile temporare pot fi utilizate numai în limitele capacității lor portante dovedite."],"b2-baggertransport":["Ce este important atunci când transportați un excavator pe un încărcător redus?","Mașina este dusă la următorul șantier.","Lăsați echipamentul de lucru să iasă liber peste margine.","Țineți ușa cabinei deschisă în timp ce conduceți.","Asigurați mașina conform specificațiilor de transport și verificați echipamentul de încărcare.","Încuietorile de transport și instalațiile de încărcare adecvate împiedică alunecarea și căderea."],"b2-schaufelfuellung":["De ce un încărcător pe roți nu are voie să conducă rapid cu cupa ridicată sus?","Sarcina este grea și solul este neuniform.","Un centru de greutate ridicat poate crește riscul de răsturnare și probleme de vizibilitate.","Cupa se stabilizează automat la viteze mari.","Înălțimea lopeții este irelevantă pentru stabilitate.","Un centru de greutate ridicat înrăutățește de obicei stabilitatea la conducere și la viraj."],"b2-fussgaenger":["Cum te comporți când manevrezi lângă pietoni?","Accesul pe șantier este și o potecă.","Folosiți lopata pentru a direcționa pietonii în lateral.","Efectuați mișcarea de conducere numai atunci când zona este liberă și gestionabilă în siguranță.","Doar claxonați o dată și continuați încet, fără vizibilitate.","Traficul de vehicule și de pasageri trebuie să fie separat efectiv sau coordonat în siguranță."],"b2-ueberlastwarnung":["La ridicare, mașina raportează suprasarcină. ce faci?","O sarcină ridicată atinge limitele admise.","Opriți avertismentul și continuați să îl ridicați neschimbat.","Strângeți încărcătura brusc în timp ce mașina funcționează.","Opriți mișcările periculoase și corectați în siguranță situația de încărcare.","Avertismentele de suprasarcină indică posibile încălcări ale limitelor și riscuri de stabilitate."],"b2-wasserleitung":["În timpul săpatului, o țeavă necunoscută este descoperită. Ce se aplică?","Linia nu este prezentată în planurile de construcție.","Opriți munca în zona afectată și identificați linia profesional.","Încercați să mutați firul cu lopata excavatorului.","Continuați să sapați direct sub linie fără a verifica.","Liniile necunoscute pot cauza pericole electrice, de gaz sau de apă."],"b2-hangefahrt":["Cum conduci un excavator pe o pantă abruptă?","Traseul planificat duce pe o pantă.","Conduceți peste pantă indiferent de limitele producătorului.","Respectați înclinația admisă și stilul de conducere prescris al mașinii.","Rotiți brațul departe pentru a echilibra vehiculul.","Panta admisă depinde de mașină, de suprafață și de informațiile producătorului."],"b2-schlechtebeleuchtung":["Când lucrați într-o groapă întunecată, vizibilitatea este inadecvată. Ce este corect?","Cu greu poți vedea oamenii și obstacolele.","Măriți viteza de săpare pentru a finaliza rapid operația.","Nu folosiți luminile în timp ce motorul este pornit.","Opriți lucrul până când zonele periculoase sunt suficient de vizibile.","Vizibilitatea sigură a zonelor de conducere și de lucru este necesară pentru mișcările controlate ale mașinii."],"b2-kettenverschleiss":["În timpul verificării zilnice, se observă o cale de omidă deteriorată. ce faci?","O conexiune în lanț prezintă o deteriorare clară.","Nu continuați să utilizați mașina necontrolată și raportați orice deteriorare.","Continuați să conduceți cu viteză mare, astfel încât lanțul să se îndrepte.","Continuați să lucrați numai pe teren moale fără a verifica.","Deteriorarea unității poate afecta controlabilitatea și stabilitatea."],"b2-ladearbeiten":["Încarci un camion cu excavatorul. Ce este important?","Șoferul camionului rămâne aproape de zona de încărcare.","Treceți găleata peste cabina șoferului neprotejat.","Preveniți oamenii să rămână în zona periculoasă și coordonați procesele.","Începeți încărcarea fără a comunica cu șoferul.","La încărcare există riscul de cădere a materialului și de mișcări de balansare."],"b2-arbeitsunterbrechung":["Întrerupeți lucrările de excavare pentru o întâlnire. Ce se aplică?","Aparatul trebuie să stea câteva minute fără a fi utilizat.","Lăsați lopata ridicată drept marker.","Lăsați mașina nesupravegheată cu tracțiunea cuplată.","Așezați utilajul în siguranță și asigurați-l împotriva utilizării accidentale.","Chiar și întreruperile scurte necesită o stare sigură a mașinii."],"b2-rollmaterial":["Materialul liber poate cădea atunci când este transportat cu încărcătorul pe pneuri. Ce este corect?","Încărcătorul conduce aproape de angajați.","Ridicați încărcătura în siguranță și alegeți un stil de condus sigur cu o poziție adecvată a lopeții.","Ridicați lopata cât mai sus posibil, astfel încât zona înconjurătoare să aibă o vedere clară.","Ridicați sarcina fără a limita umplerea găleții.","Încărcăturile libere, pozițiile înalte ale cupei și vizibilitatea slabă pot pune în pericol oamenii și traficul."]};
